import type { Soru } from "../sorular";

export const P02: Soru[] = [
  { id: "p02-001", k: "Uzay", s: "Yıldızlar enerjilerini temelde hangi süreçle üretir?", d: "Nükleer füzyon", y: ["Nükleer fisyon", "Kimyasal yanma"], a: "Yıldızın çekirdeğinde hafif atom çekirdekleri birleşip daha ağır çekirdeklere dönüşür. Bu sırada açığa çıkan enerji yıldızı parlatır." },
  { id: "p02-002", k: "Uzay", s: "Güneş benzeri yıldızların çekirdeğinde hidrojen hangi elemente dönüşür?", d: "Helyum", y: ["Karbon", "Demir"], a: "Dört hidrojen çekirdeği bir dizi tepkimeyle bir helyum çekirdeğine dönüşür. Aradaki küçük kütle farkı enerji olarak açığa çıkar." },
  { id: "p02-003", k: "Uzay", s: "Yıldızlar nerede doğar?", d: "Gaz ve toz bulutlarında", y: ["Kara deliklerin içinde", "Gezegenlerin çekirdeğinde"], a: "Soğuk ve yoğun gaz bulutlarının bazı bölgeleri kendi çekimiyle çöker. Çöken madde ısınır ve sonunda çekirdekte füzyon başlar." },
  { id: "p02-004", k: "Uzay", s: "Bir yıldızın ne kadar yaşayacağını en çok hangi özelliği belirler?", d: "Kütlesi", y: ["Rengi", "Galaksideki konumu"], a: "Kütle, yıldızın ne kadar sıcak yanacağını ve sonunun nasıl olacağını büyük ölçüde belirler." },
  { id: "p02-005", k: "Uzay", s: "Büyük kütleli yıldızlar neden küçüklerden daha kısa yaşar?", d: "Yakıtlarını çok daha hızlı tükettikleri için", y: ["Daha az yakıtları olduğu için", "Daha soğuk oldukları için"], a: "Büyük yıldızların daha çok yakıtı vardır, ama çekirdekleri çok sıcak olduğu için bu yakıtı kat kat hızlı harcarlar." },
  { id: "p02-007", k: "Uzay", s: "Çok büyük kütleli bir yıldızın ömrü genellikle nasıl sona erer?", d: "Süpernova patlamasıyla", y: ["Sessizce soğuyarak", "Gezegene dönüşerek"], a: "Çekirdeği çöken dev yıldız büyük bir patlamayla dış katmanlarını fırlatır. Geride nötron yıldızı ya da kara delik kalabilir." },
  { id: "p02-008", k: "Uzay", s: "Kırmızı dev nedir?", d: "Şişmiş, yaşlı bir yıldız", y: ["Yeni doğmuş sıcak bir yıldız", "Kırmızı renkli bir galaksi"], a: "Çekirdeğindeki hidrojen azalan yıldız dışa doğru şişer. Yüzeyi genişleyip soğuduğu için kırmızımsı görünür." },
  { id: "p02-009", k: "Uzay", s: "Bir yıldızın rengi bize en çok neyi anlatır?", d: "Yüzey sıcaklığını", y: ["Uzaklığını", "Kaç gezegeni olduğunu"], a: "Sıcak cisimler daha kısa dalga boylu ışık yayar. Bu yüzden yıldızın rengi yüzey sıcaklığının iyi bir göstergesidir." },
  { id: "p02-010", k: "Uzay", s: "En sıcak yıldızlar hangi renkte görünür?", d: "Mavi", y: ["Kırmızı", "Turuncu"], a: "Mavi yıldızların yüzeyi on binlerce dereceye ulaşabilir. Kırmızı yıldızlar ise görece soğuktur." },
  { id: "p02-011", k: "Uzay", s: "Samanyolu'nda en yaygın yıldız türü hangisi?", d: "Kırmızı cüceler", y: ["Mavi devler", "Kırmızı süperdevler"], a: "Kırmızı cüceler küçük ve sönük oldukları için neredeyse hiçbiri çıplak gözle görülmez, ama galaksideki yıldızların büyük çoğunluğunu oluştururlar." },
  { id: "p02-012", k: "Uzay", s: "Bir beyaz cüce yaklaşık hangi büyüklüktedir?", d: "Dünya kadar", y: ["Güneş kadar", "Bir şehir kadar"], a: "Beyaz cüce, Güneş'e yakın bir kütleyi Dünya boyutunda bir hacme sıkıştırır. Bu yüzden son derece yoğundur." },
  { id: "p02-013", k: "Uzay", s: "Gezegenimsi bulutsu aslında nedir?", d: "Ölen yıldızın saçtığı gaz kabuğu", y: ["Gezegenlerin doğduğu bulut", "Bir gezegen kümesi"], a: "Adı yanıltıcıdır. Eski teleskoplarda gezegen gibi yuvarlak göründükleri için bu adı aldılar; gezegenlerle ilgileri yoktur." },
  { id: "p02-014", k: "Uzay", s: "Vücudumuzdaki karbon ve oksijen atomları ilk olarak nerede oluştu?", d: "Yıldızların içinde", y: ["Dünya'nın çekirdeğinde", "Okyanusların dibinde"], a: "Büyük Patlama'da yalnız en hafif elementler oluştu. Karbon, oksijen ve daha ağır elementleri yıldızlar üretti ve ölürken uzaya saçtı." },
  { id: "p02-015", k: "Uzay", s: "Büyük yıldızların çekirdeğinde biriken ve füzyonu artık enerji vermeyen element hangisi?", d: "Demir", y: ["Helyum", "Neon"], a: "Demiri kaynaştırmak enerji üretmez, tersine enerji tüketir. Çekirdekte demir birikince yıldız çöküşe doğru gider." },
  { id: "p02-016", k: "Uzay", s: "Kuzey Yıldızı'nın bilinen adı nedir?", d: "Polaris", y: ["Sirius", "Vega"], a: "Polaris, Küçük Ayı takımyıldızında yer alır ve kuzey gök kutbuna çok yakındır." },
  { id: "p02-017", k: "Uzay", s: "Kuzey Yıldızı yön bulmada neden işe yarar?", d: "Gökyüzünde neredeyse sabit durduğu için", y: ["En parlak yıldız olduğu için", "Hep doğudan doğduğu için"], a: "Yaygın sanının aksine Polaris en parlak yıldız değildir. Kuzey gök kutbuna çok yakın olduğu için gece boyunca hemen hemen yerinden oynamaz." },
  { id: "p02-018", k: "Uzay", s: "Güneş hariç, gece gökyüzünün en parlak yıldızı hangisi?", d: "Sirius", y: ["Polaris", "Betelgeuse"], a: "Sirius hem görece yakın hem de Güneş'ten çok daha parlak bir yıldızdır. Yaklaşık 8,6 ışık yılı uzaktadır." },
  { id: "p02-019", k: "Uzay", s: "Sirius hangi takımyıldızda yer alır?", d: "Büyük Köpek", y: ["Orion", "Aslan"], a: "Sirius'a eski çağlarda \"Köpek Yıldızı\" da denirdi. Mısırlılar onun şafakta görünmesini Nil taşkınlarıyla ilişkilendirirdi." },
  { id: "p02-020", k: "Uzay", s: "Güneş'ten sonra bize en yakın yıldız hangisi?", d: "Proxima Centauri", y: ["Sirius", "Betelgeuse"], a: "Proxima Centauri yaklaşık 4,2 ışık yılı uzaklıktadır. Çok sönük olduğu için çıplak gözle görülmez." },
  { id: "p02-021", k: "Uzay", s: "Proxima Centauri ne tür bir yıldızdır?", d: "Kırmızı cüce", y: ["Mavi dev", "Beyaz cüce"], a: "Proxima, Güneş'ten çok daha küçük ve soğuk bir kırmızı cücedir. Ara sıra güçlü parlamalar yapar." },
  { id: "p02-022", k: "Uzay", s: "Alfa Centauri sistemi kaç yıldızdan oluşur?", d: "Üç", y: ["Bir", "Beş"], a: "Sistemde birbirine yakın Alfa Centauri A ve B ile onlardan uzakta dolanan Proxima Centauri bulunur." },
  { id: "p02-023", k: "Uzay", s: "Kırmızı süperdev Betelgeuse hangi takımyıldızdadır?", d: "Orion", y: ["Büyük Ayı", "Akrep"], a: "Betelgeuse, Orion'un omzunda parlayan turuncu-kırmızı yıldızdır. Ömrünün sonuna yaklaştığı ve bir gün süpernova olacağı düşünülür." },
  { id: "p02-024", k: "Uzay", s: "Orion takımyıldızında yan yana dizilmiş üç yıldıza ne denir?", d: "Orion'un Kemeri", y: ["Orion'un Tacı", "Orion'un Kalkanı"], a: "Bu üç yıldız gökyüzünde kolayca bulunur. Kemerin çizgisi uzatılınca Sirius'a ulaşılır." },
  { id: "p02-025", k: "Uzay", s: "Orion takımyıldızındaki parlak mavi-beyaz süperdev hangisi?", d: "Rigel", y: ["Betelgeuse", "Antares"], a: "Orion'da kırmızı Betelgeuse ile mavi-beyaz Rigel karşılıklı köşelerde durur. Renk farkı sıcaklık farkını gösterir." },
  { id: "p02-026", k: "Uzay", s: "Orion Bulutsusu nedir?", d: "Yeni yıldızların doğduğu bir bölge", y: ["Bir süpernova kalıntısı", "Komşu bir galaksi"], a: "Orion'un kılıcında soluk bir leke olarak görülür. Yaklaşık 1.300 ışık yılı uzaklıktaki bu bulutta yeni yıldızlar oluşmaktadır." },
  { id: "p02-027", k: "Uzay", s: "Yengeç Bulutsusu nedir?", d: "Bir süpernova kalıntısı", y: ["Yıldız doğum bölgesi", "Sarmal bir galaksi"], a: "1054 yılında gözlenen bir yıldız patlamasının kalıntısıdır. Patlamayı Çinli gökbilimciler kayda geçirmiştir." },
  { id: "p02-028", k: "Uzay", s: "Yengeç Bulutsusu'nun merkezinde ne bulunur?", d: "Bir pulsar", y: ["Bir kara delik", "Bir kırmızı dev"], a: "Merkezdeki nötron yıldızı saniyede yaklaşık 30 kez döner ve her dönüşte bize doğru ışın atımı gönderir." },
  { id: "p02-029", k: "Uzay", s: "Büyük Ayı takımyıldızındaki yedi parlak yıldızın oluşturduğu şekle ne denir?", d: "Büyük Kepçe", y: ["Ülker", "Orion'un Kemeri"], a: "Kepçenin ağzındaki iki yıldızı birleştiren çizgi uzatılınca Kuzey Yıldızı'na ulaşılır." },
  { id: "p02-030", k: "Uzay", s: "Kuzey Yıldızı hangi takımyıldızın parçasıdır?", d: "Küçük Ayı", y: ["Büyük Ayı", "Kraliçe"], a: "Polaris, Küçük Ayı'nın kuyruğunun ucunda yer alır. Küçük Ayı da Büyük Ayı gibi kepçeye benzer." },
  { id: "p02-031", k: "Uzay", s: "Uluslararası Astronomi Birliği gökyüzünü resmi olarak kaç takımyıldıza böler?", d: "88", y: ["12", "48"], a: "Bu liste 1922'de kabul edildi. Antik çağda Batlamyus 48 takımyıldız tanımlamıştı." },
  { id: "p02-032", k: "Uzay", s: "Burç kuşağı takımyıldızları gökyüzünde hangi yol boyunca dizilir?", d: "Güneş'in yıllık görünür yolu", y: ["Samanyolu şeridi", "Kuzey ufku"], a: "Bu yola ekliptik denir. Güneş bir yıl boyunca bu yol üzerindeki takımyıldızların önünden geçiyormuş gibi görünür." },
  { id: "p02-033", k: "Uzay", s: "Ülker (Pleiades) nedir?", d: "Bir açık yıldız kümesi", y: ["Bir galaksi", "Bir gezegenimsi bulutsu"], a: "Ülker, birlikte doğmuş genç yıldızlardan oluşan bir kümedir. Çıplak gözle altı-yedi yıldızı seçilebilir." },
  { id: "p02-034", k: "Uzay", s: "Ülker yıldız kümesi hangi takımyıldızda yer alır?", d: "Boğa", y: ["İkizler", "Terazi"], a: "Ülker, Boğa takımyıldızında Aldebaran'ın yakınında görülür. Pek çok kültürde takvim ve tarım için işaret olarak kullanıldı." },
  { id: "p02-035", k: "Uzay", s: "Turuncu dev yıldız Aldebaran hangi takımyıldızın en parlak yıldızıdır?", d: "Boğa", y: ["Aslan", "Başak"], a: "Aldebaran, gökyüzünde boğanın gözü olarak hayal edilir. Adı Arapçada \"izleyen\" anlamına gelir." },
  { id: "p02-036", k: "Uzay", s: "Kırmızı süperdev Antares hangi takımyıldızdadır?", d: "Akrep", y: ["Yay", "Başak"], a: "Antares, akrebin kalbi olarak düşünülür. Adı \"Mars'ın rakibi\" anlamına gelir; kırmızı rengi Mars'a benzer." },
  { id: "p02-037", k: "Uzay", s: "Yaz Üçgeni'ni oluşturan üç parlak yıldız hangileri?", d: "Vega, Deneb, Altair", y: ["Sirius, Rigel, Procyon", "Polaris, Vega, Sirius"], a: "Bu üç yıldız kuzey yarımkürede yaz gecelerinde tepede parlak bir üçgen çizer. Her biri farklı bir takımyıldıza aittir." },
  { id: "p02-038", k: "Uzay", s: "Kış Üçgeni'ni oluşturan üç parlak yıldız hangileri?", d: "Sirius, Betelgeuse, Procyon", y: ["Vega, Deneb, Altair", "Polaris, Rigel, Antares"], a: "Kuzey yarımkürede kış gecelerinde görülen bu üçgen, Orion takımyıldızının hemen yanında yer alır." },
  { id: "p02-039", k: "Uzay", s: "Güney Haçı takımyıldızı yön bulmak için en çok nerede kullanılır?", d: "Güney yarımkürede", y: ["Kuzey yarımkürede", "Kuzey Kutbu'nda"], a: "Güney yarımkürede Kuzey Yıldızı görülmez. Güney Haçı'nın uzun ekseni güney yönünü bulmaya yardım eder." },
  { id: "p02-040", k: "Uzay", s: "Kraliçe (Cassiopeia) takımyıldızı gökyüzünde hangi harfe benzer?", d: "W", y: ["T", "O"], a: "Beş parlak yıldızı bir W ya da M çizer. Kuzey Yıldızı'nın, Büyük Kepçe'nin karşı tarafında yer alır." },
  { id: "p02-041", k: "Uzay", s: "Kadir (magnitüd) ölçeğinde sayı küçüldükçe yıldız nasıl görünür?", d: "Daha parlak", y: ["Daha sönük", "Daha kırmızı"], a: "Ölçek antik çağdan gelir ve terstir. En parlak yıldızların kadiri sıfıra yakın, hatta eksidir." },
  { id: "p02-042", k: "Uzay", s: "Yıldızlar neden göz kırpıyormuş gibi titreşir?", d: "Atmosferdeki hava hareketleri yüzünden", y: ["Sönüp yeniden yandıkları için", "Hızla döndükleri için"], a: "Yıldız ışığı atmosferdeki farklı sıcaklıktaki hava katmanlarından geçerken sürekli kırılır. Uzaydan bakınca yıldızlar titreşmez." },
  { id: "p02-043", k: "Uzay", s: "Gündüz yıldızları neden göremeyiz?", d: "Saçılan güneş ışığı onları bastırır", y: ["Yıldızlar gündüz söner", "Hepsi ufkun altına iner"], a: "Atmosfer güneş ışığını her yöne saçarak gökyüzünü aydınlatır. Yıldızlar orada durur, ama bu parlaklıkta seçilemez." },
  { id: "p02-044", k: "Uzay", s: "Birbirinin çevresinde dolanan iki yıldızdan oluşan sisteme ne denir?", d: "Çift yıldız", y: ["Kuasar", "Gezegenimsi bulutsu"], a: "Çift yıldızlar çok yaygındır. Birbirlerinin çevresindeki hareketleri, yıldızların kütlesini ölçmenin en iyi yollarından biridir." },
  { id: "p02-045", k: "Uzay", s: "Nova patlamaları genellikle nasıl bir sistemde olur?", d: "Beyaz cüce ve eş yıldızdan oluşan çift sistemde", y: ["Tek başına bir kırmızı cücede", "Bir gaz devi gezegende"], a: "Beyaz cüce eşinden çektiği gazı yüzeyinde biriktirir. Bu gaz bir anda tutuşunca yıldız birkaç gün içinde çok parlar." },
  { id: "p02-046", k: "Uzay", s: "Tip Ia süpernovalar gökbilimde en çok ne için kullanılır?", d: "Uzak galaksilerin uzaklığını ölçmek için", y: ["Gezegen bulmak için", "Kuyruklu yıldız izlemek için"], a: "Bu patlamaların gerçek parlaklığı birbirine çok yakındır. Ne kadar sönük göründüklerine bakarak uzaklıkları hesaplanabilir." },
  { id: "p02-047", k: "Uzay", s: "Sefeid değişkenlerinde dönem ile parlaklık arasındaki ilişkiyi kim buldu?", d: "Henrietta Leavitt", y: ["Marie Curie", "Vera Rubin"], a: "Leavitt 1900'lerin başında Harvard'da bu ilişkiyi keşfetti. Böylece Sefeidler galaksiler arası uzaklıkları ölçmede kullanılabildi." },
  { id: "p02-048", k: "Uzay", s: "Yıldızları O, B, A, F, G, K, M diye sınıflandıran sistemi geliştirmede öne çıkan isim kim?", d: "Annie Jump Cannon", y: ["Henrietta Leavitt", "Jocelyn Bell Burnell"], a: "Cannon, yüz binlerce yıldızı tayflarına göre sınıflandırdı. Bu sıralama en sıcak yıldızlardan en soğuklara doğru gider." },
  { id: "p02-049", k: "Uzay", s: "Yıldız sınıflandırmasında Güneş hangi harfle gösterilir?", d: "G", y: ["O", "M"], a: "Güneş G2 sınıfında, ana koldaki sarı bir cücedir. O sınıfı en sıcak, M sınıfı en soğuk yıldızları kapsar." },
  { id: "p02-050", k: "Uzay", s: "Dünya'nın yörüngedeki konum değişimiyle yakın yıldızların uzaklığını ölçen yönteme ne denir?", d: "Paralaks", y: ["Doppler kayması", "Kütle çekim merceği"], a: "Altı ay arayla bakıldığında yakın yıldızlar uzak arka plana göre biraz kayar. Bu küçük açıdan uzaklık hesaplanır." },
  { id: "p02-051", k: "Uzay", s: "Bir parsek yaklaşık kaç ışık yılıdır?", d: "3,26", y: ["1", "10"], a: "Parsek, paralaks açısı bir yay saniyesi olan uzaklıktır. Gökbilimciler ışık yılından çok parseği kullanır." },
  { id: "p02-052", k: "Uzay", s: "Bir yıldızın hangi elementlerden oluştuğunu nasıl anlarız?", d: "Işığını tayfına ayırarak", y: ["Uzay aracıyla örnek alarak", "Yalnız rengine bakarak"], a: "Her element ışığın belirli renklerini soğurur ya da yayar. Tayftaki bu çizgiler yıldızın kimyasal parmak izidir." },
  { id: "p02-053", k: "Uzay", s: "Yıldızlar çoğunlukla hangi elementlerden oluşur?", d: "Hidrojen ve helyum", y: ["Demir ve nikel", "Karbon ve oksijen"], a: "Tipik bir yıldızın kütlesinin yaklaşık dörtte üçü hidrojen, dörtte birine yakını helyumdur. Diğer elementler çok az yer tutar." },
  { id: "p02-054", k: "Uzay", s: "Yıldızların büyük ölçüde hidrojen ve helyumdan oluştuğunu 1925'te gösteren gökbilimci kim?", d: "Cecilia Payne", y: ["Vera Rubin", "Annie Jump Cannon"], a: "Payne doktora tezinde bu sonuca ulaştı. O dönemde yıldızların Dünya'ya benzer bileşimde olduğu sanılıyordu." },
  { id: "p02-055", k: "Uzay", s: "Hidrojen füzyonunu sürdüremeyecek kadar küçük kütleli, yıldızımsı cisme ne denir?", d: "Kahverengi cüce", y: ["Beyaz cüce", "Nötron yıldızı"], a: "Kahverengi cüceler gezegenle yıldız arasında kalır. Kütleleri Jüpiter'in birkaç katından onlarca katına kadar çıkabilir." },
  { id: "p02-056", k: "Uzay", s: "Yıldızın çekirdeğinde hidrojen yaktığı en uzun evreye ne denir?", d: "Ana kol evresi", y: ["Kırmızı dev evresi", "Beyaz cüce evresi"], a: "Yıldızlar ömürlerinin büyük kısmını ana kolda geçirir. Güneş de şu an bu evrededir." },
  { id: "p02-057", k: "Uzay", s: "Hertzsprung-Russell diyagramı neyi gösterir?", d: "Yıldızların parlaklığını ve sıcaklığını", y: ["Gezegenlerin yörüngelerini", "Galaksilerin uzaklığını"], a: "Yıldızlar bu diyagramda rastgele dağılmaz; ana kol, devler ve beyaz cüceler ayrı bölgelerde toplanır." },
  { id: "p02-058", k: "Uzay", s: "Henüz çekirdeğinde füzyon başlamamış, büzülmekte olan genç yıldıza ne denir?", d: "Önyıldız", y: ["Kahverengi cüce", "Pulsar"], a: "Önyıldız, çevresindeki gaz bulutundan madde toplayarak büyür. Çekirdek yeterince ısınınca hidrojen füzyonu başlar." },
  { id: "p02-059", k: "Uzay", s: "Bir süpernova kısa bir süre için ne kadar parlak olabilir?", d: "Bütün bir galaksi kadar", y: ["Ancak bir gezegen kadar", "Dolunay'ın yarısı kadar"], a: "Bir süpernova birkaç hafta boyunca, içinde bulunduğu galaksinin milyarlarca yıldızının toplam ışığıyla yarışabilir." },
  { id: "p02-060", k: "Uzay", s: "1987'de çıplak gözle görülen ünlü süpernova nerede patladı?", d: "Büyük Macellan Bulutu'nda", y: ["Andromeda Galaksisi'nde", "Orion Bulutsusu'nda"], a: "SN 1987A, yüzyıllardır görülen en yakın süpernovaydı. Patlamadan gelen nötrinolar da Dünya'daki dedektörlerde yakalandı." },
  { id: "p02-061", k: "Uzay", s: "Johannes Kepler'in 1604'te gökyüzünde gözlediği \"yeni yıldız\" neydi?", d: "Bir süpernova", y: ["Bir kuyruklu yıldız", "Bir meteor yağmuru"], a: "Bu patlama Samanyolu'nda gerçekleşti. O zamandan beri galaksimizde çıplak gözle görülen başka bir süpernova olmadı." },
  { id: "p02-062", k: "Uzay", s: "Tycho Brahe'nin 1572'de gördüğü yeni yıldız hangi eski inancı sarstı?", d: "Göklerin hiç değişmediği inancını", y: ["Dünya'nın yuvarlak olduğu inancını", "Ay'ın ışık yaydığı inancını"], a: "Tycho, yeni yıldızın Ay'dan çok uzakta olduğunu gösterdi. Oysa o dönemde yıldızlar âleminin değişmez olduğuna inanılıyordu." },
  { id: "p02-063", k: "Uzay", s: "Bir takımyıldızdaki yıldızlar uzayda birbirine yakın mıdır?", d: "Genellikle hayır", y: ["Evet, hepsi aynı uzaklıkta", "Evet, hepsi birbirine bağlı"], a: "Takımyıldızlar yalnız bizim bakış açımızdan oluşan desenlerdir. Aynı desendeki iki yıldız yüzlerce ışık yılı farklı uzaklıkta olabilir." },
  { id: "p02-064", k: "Uzay", s: "Uzak bir yıldıza baktığımızda onun hangi halini görürüz?", d: "Işığın yola çıktığı andaki halini", y: ["Şu anki halini", "Gelecekteki halini"], a: "Işık sonlu hızda ilerler. 500 ışık yılı uzaktaki bir yıldızı, 500 yıl önceki haliyle görürüz." },
  { id: "p02-065", k: "Uzay", s: "Karanlık bir gecede çıplak gözle aynı anda yaklaşık kaç yıldız görülebilir?", d: "Birkaç bin", y: ["Birkaç düzine", "Birkaç milyon"], a: "Işık kirliliği olmayan bir yerde gökyüzünün görünen yarısında birkaç bin yıldız seçilebilir. Şehirlerde bu sayı çok düşer." },
  { id: "p02-066", k: "Uzay", s: "Samanyolu'nda yaklaşık kaç yıldız vardır?", d: "Yüz milyarlarca", y: ["Birkaç milyon", "Birkaç bin"], a: "Tahminler genellikle 100 ile 400 milyar arasındadır. Çoğu sönük kırmızı cüce olduğu için kesin sayıyı bilmek zordur." },
  { id: "p02-067", k: "Uzay", s: "Samanyolu ne tür bir galaksidir?", d: "Çubuklu sarmal", y: ["Eliptik", "Düzensiz"], a: "Samanyolu'nun merkezinde yıldızlardan oluşan bir çubuk, çevresinde de sarmal kollar vardır." },
  { id: "p02-068", k: "Uzay", s: "Samanyolu'nun çapı yaklaşık ne kadardır?", d: "100 bin ışık yılı", y: ["1.000 ışık yılı", "10 milyon ışık yılı"], a: "Işık bile galaksimizin bir ucundan öbür ucuna yaklaşık 100 bin yılda gider. Diskin kalınlığı ise çapına göre çok incedir." },
  { id: "p02-069", k: "Uzay", s: "Güneş, Samanyolu'nun merkezine yaklaşık ne kadar uzaktadır?", d: "26 bin ışık yılı", y: ["260 ışık yılı", "2,6 milyon ışık yılı"], a: "Güneş Sistemi galaksinin merkezinde değil, diskin dış yarısında bir sarmal kolun kenarında yer alır." },
  { id: "p02-071", k: "Uzay", s: "Samanyolu'nun merkezindeki süper kütleli kara deliğin adı nedir?", d: "Yay A*", y: ["Cygnus X-1", "M87*"], a: "Yay A* (Sagittarius A*), çevresindeki yıldızların hızlı yörüngeleri izlenerek ortaya çıkarıldı. Bu çalışmalar 2020 Nobel Fizik Ödülü'nü kazandı." },
  { id: "p02-072", k: "Uzay", s: "Samanyolu'nun merkezindeki kara deliğin kütlesi yaklaşık ne kadardır?", d: "4 milyon Güneş kütlesi", y: ["4 Güneş kütlesi", "4 trilyon Güneş kütlesi"], a: "Bu dev kütle, Merkür'ün yörüngesinden bile küçük bir bölgeye sığar." },
  { id: "p02-073", k: "Uzay", s: "Samanyolu'nun merkezi gökyüzünde hangi takımyıldız yönündedir?", d: "Yay", y: ["Orion", "Büyük Ayı"], a: "Yaz gecelerinde Yay takımyıldızı yönünde Samanyolu şeridi en parlak ve en kalın halini alır." },
  { id: "p02-074", k: "Uzay", s: "Gökyüzündeki soluk Samanyolu şeridi aslında nedir?", d: "Sayısız uzak yıldızın ışığı", y: ["Atmosferdeki ince bulutlar", "Ay ışığının yansıması"], a: "Galileo 1610 civarında teleskobunu bu şeride çevirip onun tek tek yıldızlardan oluştuğunu gördü." },
  { id: "p02-075", k: "Uzay", s: "Andromeda Galaksisi ne tür bir galaksidir?", d: "Sarmal", y: ["Eliptik", "Düzensiz"], a: "Andromeda, Samanyolu'na benzeyen büyük bir sarmal galaksidir ve Yerel Grup'un en büyük üyesidir." },
  { id: "p02-076", k: "Uzay", s: "Andromeda'dan gelen ışık yaklaşık ne kadar önce yola çıktı?", d: "2,5 milyon yıl önce", y: ["2.500 yıl önce", "2,5 milyar yıl önce"], a: "Andromeda yaklaşık 2,5 milyon ışık yılı uzaktadır. Yani Andromeda'yı milyonlarca yıl önceki haliyle görürüz." },
  { id: "p02-077", k: "Uzay", s: "Andromeda Galaksisi Samanyolu'na göre nasıl hareket ediyor?", d: "Bize yaklaşıyor", y: ["Bizden uzaklaşıyor", "Hiç hareket etmiyor"], a: "Uzak galaksilerin çoğu bizden uzaklaşır, ama Andromeda kütle çekimi yüzünden bize doğru gelir. Işığı maviye kaymıştır." },
  { id: "p02-078", k: "Uzay", s: "Andromeda Galaksisi karanlık bir gökyüzünde nasıl görülebilir?", d: "Çıplak gözle soluk bir leke olarak", y: ["Yalnız uzay teleskoplarıyla", "Hiçbir şekilde görülemez"], a: "Andromeda, çıplak gözle görülebilen en uzak cisimlerden biridir. Gözümüze ulaşan ışık milyonlarca yıllıktır." },
  { id: "p02-079", k: "Uzay", s: "Andromeda Galaksisi'nin Messier kataloğundaki numarası nedir?", d: "M31", y: ["M1", "M42"], a: "M1 Yengeç Bulutsusu, M42 ise Orion Bulutsusu'dur. Messier kataloğunda 110 cisim bulunur." },
  { id: "p02-080", k: "Uzay", s: "Charles Messier ünlü kataloğunu neden hazırladı?", d: "Kuyruklu yıldızlarla karıştırılmasınlar diye", y: ["Denizcilere yön göstermek için", "Yeni takımyıldızlar tanımlamak için"], a: "Kuyruklu yıldız avcısı Messier, bulanık görünen ama hareket etmeyen cisimleri listeledi. Bu liste bugün amatörlerin gözdesidir." },
  { id: "p02-081", k: "Uzay", s: "Büyük ve Küçük Macellan Bulutları nedir?", d: "Samanyolu'nun uydu galaksileri", y: ["Yıldız doğum bulutsuları", "Kuyruklu yıldız bulutları"], a: "Bu iki küçük galaksi Samanyolu'nun çevresinde dolanır. Güney yarımküreden çıplak gözle bulut parçaları gibi görünürler." },
  { id: "p02-082", k: "Uzay", s: "Yerel Grup nedir?", d: "Samanyolu'nun da üyesi olduğu galaksi grubu", y: ["Güneş'e yakın yıldızların kümesi", "Bir galaksi sınıfı"], a: "Yerel Grup'ta Samanyolu, Andromeda ve Üçgen Galaksisi ile onlarca cüce galaksi bulunur." },
  { id: "p02-083", k: "Uzay", s: "Edwin Hubble 1920'lerde Andromeda hakkında neyi gösterdi?", d: "Samanyolu dışında ayrı bir galaksi olduğunu", y: ["Samanyolu'nun içinde bir bulutsu olduğunu", "Bir kara delik olduğunu"], a: "Hubble, Andromeda'daki Sefeid yıldızlarıyla uzaklığını ölçtü. Böylece evrenin Samanyolu'ndan çok daha büyük olduğu anlaşıldı." },
  { id: "p02-084", k: "Uzay", s: "Hubble yasasına göre bir galaksi ne kadar uzaktaysa bizden nasıl uzaklaşır?", d: "O kadar hızlı", y: ["O kadar yavaş", "Hepsi aynı hızla"], a: "Bu ilişki evrenin genişlediğini gösterir. Uzayın kendisi genişledikçe uzak galaksiler arasındaki mesafe daha hızlı büyür." },
  { id: "p02-085", k: "Uzay", s: "Eliptik galaksiler genel olarak nasıldır?", d: "Yaşlı yıldızlar ağırlıkta, az gaz var", y: ["Bol gaz ve hızlı yıldız oluşumu var", "Belirgin sarmal kolları var"], a: "Eliptik galaksiler küre ya da yumurta biçimindedir. Yeni yıldız yapacak gazları azaldığı için genellikle sarımsı-kırmızı görünürler." },
  { id: "p02-086", k: "Uzay", s: "Karanlık maddeye neden \"karanlık\" denir?", d: "Işık yaymadığı ve yansıtmadığı için", y: ["Siyah renkli olduğu için", "Yalnız gece etkili olduğu için"], a: "Karanlık madde doğrudan görülemez. Varlığı yalnız çevresindeki yıldızlara ve galaksilere uyguladığı kütle çekiminden anlaşılır." },
  { id: "p02-087", k: "Uzay", s: "Galaksilerin dış kısımlarının beklenenden hızlı dönmesini ölçerek karanlık maddeye güçlü kanıt bulan kim?", d: "Vera Rubin", y: ["Henrietta Leavitt", "Cecilia Payne"], a: "Rubin 1970'lerde galaksilerin kenarlarındaki yıldızların da merkeze yakınlar kadar hızlı döndüğünü gösterdi. Görünen madde bunu açıklamaya yetmez." },
  { id: "p02-088", k: "Uzay", s: "Güneş Sistemi Samanyolu'nun neresinde bulunur?", d: "Bir sarmal kolda, merkezden uzakta", y: ["Tam merkezde", "Galaksinin dışında"], a: "Güneş, Orion Kolu denen küçük bir kolda yer alır. Bu konum, galaksinin kalabalık merkezinden oldukça uzaktır." },
  { id: "p02-089", k: "Uzay", s: "Kuasar nedir?", d: "Etkin bir dev kara deliğin çevresindeki parlak ışık", y: ["Çok yakın bir yıldız türü", "Bir kuyruklu yıldız türü"], a: "Kara deliğe düşen gaz aşırı ısınıp ışır. Bazı kuasarlar içinde bulundukları galaksinin tüm yıldızlarından daha parlaktır." },
  { id: "p02-090", k: "Uzay", s: "Samanyolu'nu yandan görebilseydik nasıl görünürdü?", d: "Ortası şişkin ince bir disk", y: ["Kusursuz bir küre", "İçi boş bir halka"], a: "Sarmal galaksilerin diski çapına göre çok incedir. Merkezde ise yıldızların yoğunlaştığı bir şişkinlik bulunur." },
  { id: "p02-091", k: "Uzay", s: "Yüz binlerce yaşlı yıldızın küre biçiminde sıkıca toplandığı kümelere ne denir?", d: "Küresel küme", y: ["Açık küme", "Gezegenimsi bulutsu"], a: "Küresel kümeler galaksinin çevresinde dolanır ve en yaşlı yıldızlardan bazılarını barındırır." },
  { id: "p02-092", k: "Uzay", s: "Ülker gibi açık yıldız kümeleri küresel kümelere göre genellikle nasıldır?", d: "Daha genç ve daha dağınık", y: ["Daha yaşlı ve daha yoğun", "Daha büyük ve daha parlak"], a: "Açık kümeler aynı buluttan yakın zamanda doğmuş birkaç yüz ile birkaç bin yıldız içerir. Zamanla dağılırlar." },
  { id: "p02-093", k: "Uzay", s: "Ünlü Atbaşı Bulutsusu hangi takımyıldızda yer alır?", d: "Orion", y: ["Büyük Ayı", "Kuğu"], a: "Atbaşı, arkasındaki parlak gazın önünde siluet gibi duran karanlık bir toz bulutudur. Şekli bir at başına benzer." },
  { id: "p02-094", k: "Uzay", s: "Hubble'ın ünlü \"Yaratılış Sütunları\" fotoğrafı hangi bulutsuda çekildi?", d: "Kartal Bulutsusu", y: ["Yengeç Bulutsusu", "Halka Bulutsusu"], a: "Bu sütunlar, içlerinde yeni yıldızların oluştuğu dev gaz ve toz kütleleridir. Fotoğraf ilk kez 1995'te yayımlandı." },
  { id: "p02-095", k: "Uzay", s: "Resmi bir takımyıldız olmayan, tanıdık yıldız desenlerine ne denir?", d: "Asterizm", y: ["Burç", "Bulutsu"], a: "Büyük Kepçe ve Orion'un Kemeri asterizm örnekleridir. Asterizmler bir takımyıldızın parçası olabilir ya da birkaçını kapsayabilir." },
  { id: "p02-096", k: "Uzay", s: "Gece gökyüzünün en parlak ikinci yıldızı hangisi?", d: "Canopus", y: ["Polaris", "Deneb"], a: "Canopus, Sirius'tan sonra en parlak yıldızdır. Güney gökyüzünde yer aldığı için Türkiye'nin büyük bölümünden görülmez." },
  { id: "p02-097", k: "Uzay", s: "Arcturus yıldızı hangi takımyıldızın en parlak yıldızıdır?", d: "Çoban", y: ["Aslan", "Başak"], a: "Turuncu dev Arcturus, Büyük Kepçe'nin sapındaki kavis uzatılarak kolayca bulunabilir." },
  { id: "p02-098", k: "Uzay", s: "Vega yıldızı hangi takımyıldızdadır?", d: "Çalgı", y: ["Kuğu", "Kartal"], a: "Lir olarak da bilinen Çalgı takımyıldızındaki Vega, Yaz Üçgeni'nin en parlak köşesidir." },
  { id: "p02-099", k: "Uzay", s: "Spika yıldızı hangi takımyıldızın en parlak yıldızıdır?", d: "Başak", y: ["Akrep", "Terazi"], a: "Spika, Başak takımyıldızında mavi-beyaz parlar. Aslında birbirine çok yakın dolanan iki yıldızdan oluşur." },
  { id: "p02-100", k: "Uzay", s: "Regulus yıldızı hangi takımyıldızdadır?", d: "Aslan", y: ["Boğa", "Yengeç"], a: "Regulus, aslanın kalbi olarak bilinir. Ekliptiğe çok yakın olduğu için Ay zaman zaman önünden geçer." },
  { id: "p02-101", k: "Uzay", s: "Kara delik nedir?", d: "Işığın bile kaçamadığı çekime sahip bölge", y: ["İçi boş dev bir yıldız", "Uzayda açılmış bir tünel"], a: "Kara delikte madde öyle küçük bir hacme sıkışır ki, belli bir sınırın içinden ışık dahil hiçbir şey dışarı çıkamaz." },
  { id: "p02-102", k: "Uzay", s: "Kara deliğin \"olay ufku\" nedir?", d: "Ötesinden geri dönüşün olmadığı sınır", y: ["Kara deliğin katı yüzeyi", "Çevresindeki toz halkası"], a: "Olay ufku bir yüzey değil, bir sınırdır. Bu sınırı geçen ışık ya da madde bir daha dışarı çıkamaz." },
  { id: "p02-103", k: "Uzay", s: "Yıldız kütleli kara delikler nasıl oluşur?", d: "Dev bir yıldızın çekirdeği çöktüğünde", y: ["İki gezegen çarpıştığında", "Bir kuyruklu yıldız buharlaştığında"], a: "Çok büyük kütleli bir yıldızın yakıtı bitince çekirdek kendi ağırlığı altında çöker. Çöküş durdurulamazsa kara delik oluşur." },
  { id: "p02-104", k: "Uzay", s: "Bir kara deliğin ilk doğrudan görüntüsü hangi yıl yayımlandı?", d: "2019", y: ["2009", "1999"], a: "Görüntü, kara deliğin çevresindeki parlak gaz halkasını ve ortadaki karanlık gölgeyi gösteriyordu." },
  { id: "p02-105", k: "Uzay", s: "2019'da görüntülenen ilk kara delik hangi galaksinin merkezindedir?", d: "M87", y: ["Samanyolu", "Andromeda"], a: "M87'nin merkezindeki kara delik yaklaşık 6,5 milyar Güneş kütlesindedir ve bize yaklaşık 55 milyon ışık yılı uzaktadır." },
  { id: "p02-106", k: "Uzay", s: "İlk kara delik görüntüsünü elde eden proje hangisidir?", d: "Olay Ufku Teleskobu", y: ["Hubble Uzay Teleskobu", "James Webb Uzay Teleskobu"], a: "Olay Ufku Teleskobu, dünyanın dört bir yanındaki radyo teleskoplarını birleştirerek Dünya büyüklüğünde sanal bir teleskop gibi çalışır." },
  { id: "p02-107", k: "Uzay", s: "Olay Ufku Teleskobu 2022'de hangi kara deliğin görüntüsünü yayımladı?", d: "Samanyolu'nun merkezindeki Yay A*", y: ["Andromeda'nın merkezindeki", "Cygnus X-1"], a: "Kendi galaksimizin merkezindeki kara deliğin ilk görüntüsü, M87'dekine benzer bir parlak halka gösterdi." },
  { id: "p02-108", k: "Uzay", s: "Kara deliğe düşen bir cismin boyuna uzayıp incelmesine halk arasında ne denir?", d: "Spagettileşme", y: ["Buharlaşma", "Kristalleşme"], a: "Cismin kara deliğe yakın ucu uzak ucundan çok daha güçlü çekilir. Bu fark cismi makarna gibi uzatır." },
  { id: "p02-109", k: "Uzay", s: "Stephen Hawking'in kuramına göre kara delikler zamanla ne yapabilir?", d: "Çok yavaş ışıyıp kütle kaybedebilir", y: ["Işıktan hızlı hareket edebilir", "Yeniden yıldıza dönüşebilir"], a: "Bu kuramsal ışımaya Hawking ışıması denir. Yıldız kütleli kara delikler için o kadar zayıftır ki henüz gözlenememiştir." },
  { id: "p02-110", k: "Uzay", s: "Kuramda kara deliğin merkezindeki sonsuz yoğunluk noktasına ne denir?", d: "Tekillik", y: ["Olay ufku", "Kuasar"], a: "Genel görelilik merkezde yoğunluğun sonsuza gittiğini söyler. Fizikçiler bunu kuramın sınırına ulaşıldığının işareti sayar." },
  { id: "p02-111", k: "Uzay", s: "Güneş aynı kütlede bir kara deliğe dönüşseydi gezegenlerin yörüngeleri ne olurdu?", d: "Değişmezdi", y: ["Gezegenler içine çekilirdi", "Gezegenler uzaya fırlardı"], a: "Uzaktan bakınca kara deliğin çekimi aynı kütledeki bir yıldızınkiyle aynıdır. Yörüngeler değişmez, ama ortalık karanlık ve soğuk olurdu." },
  { id: "p02-112", k: "Uzay", s: "Kara delik olarak kabul edilen ilk cisimlerden Cygnus X-1 hangi takımyıldızdadır?", d: "Kuğu", y: ["Yay", "Orion"], a: "Cygnus X-1, dev bir yıldızın görünmez bir eşle dolandığı bir sistemdir. Eşin yaydığı X-ışınları onun kara delik olduğunu gösterir." },
  { id: "p02-113", k: "Uzay", s: "\"Kara delik\" terimini 1960'larda yaygınlaştıran fizikçi kimdir?", d: "John Wheeler", y: ["Isaac Newton", "Edwin Hubble"], a: "Wheeler terimi 1967'deki bir konuşmasında kullandı. Daha önce bu cisimler için \"çökmüş yıldız\" gibi adlar kullanılıyordu." },
  { id: "p02-114", k: "Uzay", s: "Genel göreliliğin kara deliği betimleyen ilk çözümünü 1916'da kim buldu?", d: "Karl Schwarzschild", y: ["Niels Bohr", "Edwin Hubble"], a: "Schwarzschild bu çözümü Birinci Dünya Savaşı'nda cephedeyken buldu. Olay ufkunun yarıçapı bugün onun adıyla anılır." },
  { id: "p02-115", k: "Uzay", s: "Kütle çekim dalgaları ilk kez hangi yıl doğrudan algılandı?", d: "2015", y: ["1915", "1969"], a: "Sinyal Eylül 2015'te yakalandı, Şubat 2016'da duyuruldu. Bu buluş 2017 Nobel Fizik Ödülü'nü getirdi." },
  { id: "p02-116", k: "Uzay", s: "İlk algılanan kütle çekim dalgası hangi olaydan geliyordu?", d: "İki kara deliğin birleşmesi", y: ["Bir süpernova", "Büyük Patlama"], a: "Yaklaşık 1,3 milyar ışık yılı uzaktaki iki kara delik birbirinin çevresinde dönerek birleşti. Uzay-zamanda oluşan titreşim Dünya'ya ulaştı." },
  { id: "p02-117", k: "Uzay", s: "Kütle çekim dalgalarını ilk algılayan gözlemevi hangisidir?", d: "LIGO", y: ["Arecibo", "Hubble"], a: "LIGO, ABD'deki iki dev lazer dedektöründen oluşur. Kollarındaki uzunluk değişimi bir protonun çapından çok daha küçüktür." },
  { id: "p02-118", k: "Uzay", s: "Kütle çekim dalgalarını öngören kuram hangisidir?", d: "Einstein'ın genel görelilik kuramı", y: ["Newton'ın kütle çekim yasası", "Kuantum mekaniği"], a: "Einstein 1916'da bu dalgaları öngördü, ama ölçülemeyecek kadar zayıf olduklarını düşünüyordu. Doğrudan algılanmaları yaklaşık 100 yıl sürdü." },
  { id: "p02-119", k: "Uzay", s: "Nötron yıldızı nedir?", d: "Dev bir yıldızın çökmüş çekirdeği", y: ["Yeni doğmuş bir yıldız", "Bir gaz devi gezegen"], a: "Süpernova sonrası geriye kalan çekirdekte protonlar ve elektronlar birleşip nötronlara dönüşür. Ortaya inanılmaz yoğun bir cisim çıkar." },
  { id: "p02-120", k: "Uzay", s: "Tipik bir nötron yıldızının çapı yaklaşık ne kadardır?", d: "20 kilometre", y: ["20 bin kilometre", "2 milyon kilometre"], a: "Güneş'ten daha fazla kütle, bir şehir büyüklüğünde bir küreye sıkışır." },
  { id: "p02-121", k: "Uzay", s: "Bir çay kaşığı nötron yıldızı maddesi Dünya'da yaklaşık ne kadar gelirdi?", d: "Milyarlarca ton", y: ["Birkaç kilogram", "Birkaç ton"], a: "Nötron yıldızı maddesi atom çekirdeği kadar yoğundur. Bu, bilinen en yoğun madde biçimlerinden biridir." },
  { id: "p02-122", k: "Uzay", s: "Pulsar nedir?", d: "Işın atımları yayan dönen nötron yıldızı", y: ["Zonklayan bir kırmızı dev", "Yanıp sönen bir kuyruklu yıldız"], a: "Pulsarın kutuplarından çıkan ışın, deniz feneri gibi döner. Işın Dünya'yı her taradığında bir atım algılarız." },
  { id: "p02-123", k: "Uzay", s: "İlk pulsarı 1967'de kim keşfetti?", d: "Jocelyn Bell Burnell", y: ["Vera Rubin", "Carl Sagan"], a: "Bell Burnell o sırada doktora öğrencisiydi ve radyo verilerinde düzenli atımlar fark etti. Buluş için verilen 1974 Nobel'i hocasına gitti." },
  { id: "p02-124", k: "Uzay", s: "İlk pulsar sinyaline şaka yollu verilen \"LGM-1\" adı ne anlama geliyordu?", d: "Küçük Yeşil Adamlar", y: ["Büyük Gizemli Mesaj", "Uzun Galaktik Dalga"], a: "Atımlar o kadar düzenliydi ki ekip önce yapay bir kaynak olasılığını şakayla andı. Kısa sürede doğal bir kaynak olduğu anlaşıldı." },
  { id: "p02-125", k: "Uzay", s: "Aşırı güçlü manyetik alana sahip nötron yıldızlarına ne denir?", d: "Magnetar", y: ["Kuasar", "Blazar"], a: "Magnetarların manyetik alanı, Dünya'nınkinden trilyonlarca kat güçlü olabilir. Zaman zaman güçlü X-ışını ve gama ışını patlamaları yaparlar." },
  { id: "p02-126", k: "Uzay", s: "2017'de hem kütle çekim dalgası hem ışıkla gözlenen ilk olay neydi?", d: "İki nötron yıldızının birleşmesi", y: ["İki galaksinin çarpışması", "Bir yıldızın doğuşu"], a: "Bu gözlem, böyle birleşmelerde altın ve platin gibi ağır elementlerin oluştuğuna güçlü kanıt sağladı." },
  { id: "p02-127", k: "Uzay", s: "Bir beyaz cücenin sahip olabileceği en büyük kütle yaklaşık ne kadardır?", d: "1,4 Güneş kütlesi", y: ["14 Güneş kütlesi", "140 Güneş kütlesi"], a: "Bu sınıra Chandrasekhar sınırı denir. Sınırı aşan beyaz cüce kendi ağırlığını taşıyamaz ve çöker ya da patlar." },
  { id: "p02-128", k: "Uzay", s: "Evrenin yaşı yaklaşık ne kadardır?", d: "13,8 milyar yıl", y: ["4,6 milyar yıl", "1,38 milyar yıl"], a: "Bu değer kozmik mikrodalga arka plan ölçümlerinden hesaplanır. 4,6 milyar yıl ise Güneş Sistemi'nin yaşıdır." },
  { id: "p02-129", k: "Uzay", s: "Kozmik mikrodalga arka plan ışıması nedir?", d: "Büyük Patlama'dan kalan ışığın izi", y: ["Güneş'ten gelen radyo dalgaları", "Yapay uyduların sinyalleri"], a: "Evren yaklaşık 380 bin yaşındayken ışık ilk kez serbestçe yayılabildi. O ışık, evrenin genişlemesiyle mikrodalgaya dönüşmüş olarak her yönden gelir." },
  { id: "p02-130", k: "Uzay", s: "Kozmik mikrodalga arka planı 1960'larda kazara keşfeden ikili kimdir?", d: "Arno Penzias ve Robert Wilson", y: ["Edwin Hubble ve Milton Humason", "Stephen Hawking ve Roger Penrose"], a: "İkili, antenlerindeki açıklanamayan gürültünün kaynağını ararken bu ışımayı buldu. 1978 Nobel Fizik Ödülü'nü aldılar." },
  { id: "p02-131", k: "Uzay", s: "Kozmik mikrodalga arka planın sıcaklığı yaklaşık ne kadardır?", d: "2,7 Kelvin", y: ["270 Kelvin", "2.700 Kelvin"], a: "Bu değer mutlak sıfırın yalnız 2,7 derece üzerindedir, yani yaklaşık eksi 270 santigrat derece." },
  { id: "p02-132", k: "Uzay", s: "\"Büyük Patlama\" adını ilk kullanan, kuramın karşıtı olan bilim insanı kimdir?", d: "Fred Hoyle", y: ["Georges Lemaître", "Albert Einstein"], a: "Hoyle 1949'da bir radyo programında bu ifadeyi kullandı. Kendisi evrenin başlangıcı olmadığını savunan sabit durum modelini destekliyordu." },
  { id: "p02-133", k: "Uzay", s: "Evrenin genişlediğini ve bir başlangıcı olduğunu ilk öne sürenlerden Belçikalı rahip-fizikçi kimdir?", d: "Georges Lemaître", y: ["Edwin Hubble", "Fred Hoyle"], a: "Lemaître 1927'de genişleyen evren fikrini yayımladı ve evrenin tek bir \"ilksel atom\"dan başladığını önerdi." },
  { id: "p02-134", k: "Uzay", s: "Büyük Patlama'dan sonraki ilk dakikalarda en çok hangi elementler oluştu?", d: "Hidrojen ve helyum", y: ["Demir ve altın", "Karbon ve oksijen"], a: "İlk dakikalarda hidrojen, helyum ve çok az lityum oluştu. Daha ağır elementler için yıldızların doğmasını beklemek gerekti." },
  { id: "p02-135", k: "Uzay", s: "1998'de evrenin genişlemesinin hızlandığı nasıl anlaşıldı?", d: "Uzak süpernovalar gözlenerek", y: ["Ay'a lazer gönderilerek", "Güneş lekeleri sayılarak"], a: "Uzak Tip Ia süpernovalar beklenenden sönük göründü. Bu buluş 2011 Nobel Fizik Ödülü'nü kazandı." },
  { id: "p02-136", k: "Uzay", s: "Evrenin genişlemesini hızlandıran gizemli etkene ne ad verilir?", d: "Karanlık enerji", y: ["Karanlık madde", "Antimadde"], a: "Karanlık enerjinin ne olduğu bilinmiyor. Ölçümlere göre evrenin toplam enerji içeriğinin yaklaşık yüzde 70'ini oluşturuyor." },
  { id: "p02-137", k: "Uzay", s: "Evrenin içeriğinde, atomlardan oluşan sıradan madde yaklaşık ne kadar yer tutar?", d: "Yüzde 5", y: ["Yüzde 50", "Yüzde 95"], a: "Yıldızlar, gezegenler ve biz evrenin yalnız küçük bir parçasıyız. Geri kalanı karanlık madde ve karanlık enerjiden oluşur." },
  { id: "p02-138", k: "Uzay", s: "Bir galaksinin ışığının kırmızıya kayması neyi gösterir?", d: "Bizden uzaklaştığını", y: ["Bize yaklaştığını", "Isındığını"], a: "Uzaklaşan bir kaynaktan gelen ışığın dalga boyu uzar ve tayf kırmızıya doğru kayar. Yaklaşan kaynaklarda maviye kayma görülür." },
  { id: "p02-139", k: "Uzay", s: "Işık yılı neyin birimidir?", d: "Uzaklık", y: ["Zaman", "Parlaklık"], a: "Adında \"yıl\" geçse de ışık yılı bir uzaklık ölçüsüdür: Işığın boşlukta bir yılda aldığı yoldur." },
  { id: "p02-140", k: "Uzay", s: "Bir ışık yılı yaklaşık kaç kilometredir?", d: "9,5 trilyon km", y: ["9,5 milyon km", "9,5 milyar km"], a: "Işık saniyede yaklaşık 300 bin km yol alır. Bir yıl boyunca bu hızla gidince yaklaşık 9,5 trilyon km eder." },
  { id: "p02-141", k: "Uzay", s: "Işığın boşluktaki hızı yaklaşık ne kadardır?", d: "Saniyede 300 bin km", y: ["Saniyede 300 km", "Saniyede 3 milyon km"], a: "Işık bir saniyede Dünya'nın çevresini yaklaşık 7,5 kez dolanabilir. Evrende bilinen en yüksek hız budur." },
  { id: "p02-142", k: "Uzay", s: "Büyük Patlama uzayda belirli bir noktada mı oldu?", d: "Hayır, uzayın her yerinde oldu", y: ["Evet, Samanyolu'nun merkezinde", "Evet, Güneş'in bulunduğu yerde"], a: "Büyük Patlama boş uzaya saçılan bir bomba gibi değildir. Uzayın kendisi her yerde birden genişlemeye başladı; bir merkezi yoktur." },
  { id: "p02-143", k: "Uzay", s: "Evrenin genişleme hızını gösteren değere ne ad verilir?", d: "Hubble sabiti", y: ["Planck sabiti", "Kütle çekim sabiti"], a: "Hubble sabiti, uzaklık arttıkça galaksilerin uzaklaşma hızının ne kadar arttığını gösterir. Değerinin tam olarak ne olduğu hâlâ tartışılıyor." },
  { id: "p02-144", k: "Uzay", s: "Kozmik ışınlar nedir?", d: "Uzaydan gelen yüksek enerjili parçacıklar", y: ["Yıldız ışığının görünür kısmı", "Uydulardan gelen radyo yayınları"], a: "Çoğu proton olan bu parçacıklar atmosfere çarpınca parçacık sağanakları oluşturur. 1912'de Victor Hess balonla keşfetti." },
  { id: "p02-145", k: "Uzay", s: "Kısa süreli ve son derece güçlü gama ışını parlamalarına ne denir?", d: "Gama ışını patlaması", y: ["Güneş rüzgârı", "Kutup ışığı"], a: "Bu patlamalar evrenin bilinen en enerjik olayları arasındadır. Bir kısmı dev yıldızların çöküşünden, bir kısmı nötron yıldızı birleşmelerinden gelir." },
  { id: "p02-146", k: "Uzay", s: "Latincede \"nebula\" (bulutsu) sözcüğü ne anlama gelir?", d: "Bulut, sis", y: ["Yıldız", "Işık"], a: "Teleskopta bulanık lekeler gibi görünen bu cisimlere bu yüzden bulutsu denir. Çoğu gaz ve toz bulutudur." },
  { id: "p02-147", k: "Uzay", s: "\"Galaksi\" sözcüğü Yunancada hangi kelimeden türemiştir?", d: "Süt", y: ["Işık", "Yol"], a: "Yunanca \"gala\" süt demektir. Samanyolu'nun İngilizce adı \"Milky Way\" de \"sütlü yol\" anlamına gelir." },
  { id: "p02-148", k: "Uzay", s: "Yıldızlar arasındaki boşlukta ne bulunur?", d: "Çok seyrek gaz ve toz", y: ["Hiçbir şey, tam boşluk", "Yoğun bir sıvı"], a: "Yıldızlararası ortam son derece seyrektir; santimetreküpte ortalama yalnız birkaç atom bulunur. Yeni yıldızların hammaddesi buradan gelir." },
  { id: "p02-149", k: "Uzay", s: "Kuramsal \"kara cüce\"ler neden henüz hiç gözlenmedi?", d: "Evren henüz yeterince yaşlı değil", y: ["Kara deliklerin içinde saklılar", "Fazla parlak oldukları için"], a: "Kara cüce, tamamen soğumuş bir beyaz cücedir. Bu soğuma evrenin bugünkü yaşından çok daha uzun sürer." },
  { id: "p02-150", k: "Uzay", s: "Küçük kırmızı cücelerin ömrü yaklaşık ne kadar olabilir?", d: "Trilyonlarca yıl", y: ["Birkaç milyon yıl", "Birkaç bin yıl"], a: "Kırmızı cüceler yakıtlarını çok tutumlu harcar. Bugüne kadar ömrünü tamamlamış hiçbir kırmızı cüce yoktur." },
  { id: "p02-151", k: "Uzay", s: "En büyük kütleli yıldızlar yaklaşık ne kadar yaşar?", d: "Birkaç milyon yıl", y: ["Yüz milyarlarca yıl", "Birkaç yüz yıl"], a: "Güneş yaklaşık 10 milyar yıl yaşayacak. Onlarca Güneş kütlesindeki yıldızlar ise birkaç milyon yılda yakıtlarını bitirir." },
  { id: "p02-152", k: "Uzay", s: "Büyük galaksilerin çoğunun merkezinde ne bulunduğu düşünülür?", d: "Süper kütleli kara delik", y: ["Dev bir mavi yıldız", "Boş bir bölge"], a: "Bu kara deliklerin kütlesi milyonlarca ile milyarlarca Güneş kütlesi arasındadır. Nasıl bu kadar büyüdükleri hâlâ araştırılıyor." },
  { id: "p02-153", k: "Uzay", s: "Kara deliğe doğru sarmal çizerek düşen, ısınıp parlayan gaz yapısına ne denir?", d: "Yığılma diski", y: ["Olay ufku", "Oort bulutu"], a: "Diskteki gaz sürtünmeyle milyonlarca dereceye ısınır ve X-ışını yayar. Kara deliklerin parlak görünmesinin nedeni budur." },
  { id: "p02-154", k: "Uzay", s: "Işık yaymayan kara delikleri gökbilimciler nasıl fark eder?", d: "Çevresindeki madde ve yıldızlara etkisinden", y: ["Simsiyah renklerinden", "Çıkardıkları sesten"], a: "Kara deliğin çevresinde hızla dolanan yıldızlar ya da ısınan gaz, görünmeyen dev bir kütleye işaret eder." },
  { id: "p02-155", k: "Uzay", s: "Genel göreliliğe göre güçlü kütle çekimine yakın bir saat, uzaktakine göre nasıl işler?", d: "Daha yavaş", y: ["Daha hızlı", "Tamamen aynı"], a: "Bu etki Dünya'da bile ölçülür. Uydulardaki saatler, yerdeki saatlere göre bu yüzden biraz daha hızlı işler." },
  { id: "p02-156", k: "Uzay", s: "Büyük bir kütlenin, arkasındaki uzak cismin ışığını bükmesine ne denir?", d: "Kütle çekim merceklenmesi", y: ["Kırmızıya kayma", "Paralaks"], a: "Galaksi kümeleri arkalarındaki galaksilerin görüntüsünü büyütüp yaylara çevirebilir. Gökbilimciler bunu doğal büyüteç gibi kullanır." },
  { id: "p02-157", k: "Uzay", s: "1919 Güneş tutulmasında yapılan ölçümler hangi kuramı destekledi?", d: "Einstein'ın genel göreliliği", y: ["Büyük Patlama kuramı", "Kıtaların kayması"], a: "Arthur Eddington'ın ekibi, Güneş'in yakınından geçen yıldız ışığının bükülme miktarını ölçtü. Sonuç Einstein'ı bir anda dünyaca ünlü yaptı." },
  { id: "p02-158", k: "Uzay", s: "Kuzey Yıldızı'nın ufuktan yüksekliği gözlemcinin neyine yaklaşık eşittir?", d: "Bulunduğu enleme", y: ["Bulunduğu boylama", "Denizden yüksekliğine"], a: "Ekvatorda Polaris ufka yakın görünür, Kuzey Kutbu'nda ise tam tepededir. Denizciler bu yolla enlemlerini bulurdu." },
  { id: "p02-159", k: "Uzay", s: "Dünya ekseninin yavaş yalpalaması yüzünden uzak gelecekte ne olacak?", d: "Kuzey kutup yıldızı değişecek", y: ["Yıldızların rengi değişecek", "Samanyolu görünmez olacak"], a: "Eksen yaklaşık 26 bin yılda bir tur yalpalar. Bu yüzden binlerce yıl sonra kutuba en yakın parlak yıldız Polaris olmayacak." },
  { id: "p02-160", k: "Uzay", s: "Ötegezegen nedir?", d: "Başka bir yıldızın çevresindeki gezegen", y: ["Güneş'e en uzak gezegen", "Gezegen büyüklüğünde bir yıldız"], a: "Güneş Sistemi dışındaki gezegenlere ötegezegen denir. 1990'lardan beri binlercesi keşfedildi." },
  { id: "p02-161", k: "Uzay", s: "Güneş benzeri bir yıldızın çevresinde keşfedilen ilk ötegezegen hangisidir?", d: "51 Pegasi b", y: ["Proxima b", "Kepler-22b"], a: "1995'te keşfedilen bu gezegen, yıldızına çok yakın dolanan bir gaz devidir. Bir turunu yalnız 4 günde tamamlar." },
  { id: "p02-162", k: "Uzay", s: "51 Pegasi b'yi keşfedip 2019 Nobel Fizik Ödülü'nü paylaşan ikili kimdir?", d: "Michel Mayor ve Didier Queloz", y: ["Penzias ve Wilson", "Hubble ve Humason"], a: "İkili, gezegenin çekimiyle yıldızın yaptığı küçük yalpalamayı ölçerek gezegeni buldu." },
  { id: "p02-163", k: "Uzay", s: "1992'de doğrulanan ilk ötegezegenler ne tür bir yıldızın çevresinde dolanıyordu?", d: "Bir pulsarın", y: ["Bir kırmızı devin", "Bir mavi süperdevin"], a: "Aleksander Wolszczan ve Dale Frail, pulsar atımlarındaki küçük düzensizliklerden gezegenlerin varlığını çıkardı." },
  { id: "p02-164", k: "Uzay", s: "Gezegen yıldızının önünden geçerken ışıktaki küçük düşüşü ölçen yöntem hangisidir?", d: "Geçiş yöntemi", y: ["Paralaks yöntemi", "Radar yöntemi"], a: "Bilinen ötegezegenlerin büyük kısmı bu yöntemle bulundu. Işıktaki düşüş miktarı gezegenin büyüklüğünü verir." },
  { id: "p02-165", k: "Uzay", s: "Gezegenin çekimiyle yıldızın ileri geri yalpalamasını ölçen yönteme ne denir?", d: "Dikine hız yöntemi", y: ["Geçiş yöntemi", "Doğrudan görüntüleme"], a: "Yıldız bize yaklaşıp uzaklaştıkça ışığı sırayla maviye ve kırmızıya kayar. Bu kaymadan gezegenin kütlesi tahmin edilir." },
  { id: "p02-166", k: "Uzay", s: "NASA'nın Kepler Uzay Teleskobu'nun asıl görevi neydi?", d: "Ötegezegen aramak", y: ["Güneş'i incelemek", "Kara delik görüntülemek"], a: "2009'da fırlatılan Kepler, aynı gökyüzü bölgesindeki yıldızları yıllarca izleyip binlerce gezegen adayı buldu." },
  { id: "p02-167", k: "Uzay", s: "NASA'nın 2018'de fırlatılan TESS uydusu ne arar?", d: "Yakın yıldızların ötegezegenlerini", y: ["Dünya'ya yaklaşan asteroitleri", "Karanlık madde parçacıklarını"], a: "TESS neredeyse bütün gökyüzünü tarayarak parlak ve yakın yıldızların önünden geçen gezegenleri arar." },
  { id: "p02-168", k: "Uzay", s: "Yıldızın çevresinde yüzeyde sıvı su bulunabilecek uzaklık aralığına ne denir?", d: "Yaşanabilir bölge", y: ["Roche sınırı", "Olay ufku"], a: "Bu bölgeye masaldan esinlenerek \"Goldilocks bölgesi\" de denir: Ne çok sıcak ne çok soğuk." },
  { id: "p02-169", k: "Uzay", s: "Yıldızına çok yakın dolanan gaz devi ötegezegenlere ne denir?", d: "Sıcak Jüpiter", y: ["Süper Dünya", "Buz devi"], a: "Bu gezegenler yıldızlarının çevresini birkaç günde dolanır. Varlıkları, gezegen sistemlerinin bizimkine benzemek zorunda olmadığını gösterdi." },
  { id: "p02-170", k: "Uzay", s: "\"Süper Dünya\" terimi ne tür bir gezegeni anlatır?", d: "Dünya'dan büyük, Neptün'den küçük", y: ["Dünya'nın tıpatıp aynısı", "Üzerinde yaşam bulunan"], a: "Terim yalnız büyüklüğü anlatır. Bir süper Dünya'nın yaşanabilir ya da Dünya'ya benzer olduğu anlamına gelmez." },
  { id: "p02-171", k: "Uzay", s: "TRAPPIST-1 sistemi neden ünlüdür?", d: "Dünya boyutunda yedi gezegeni var", y: ["Gökyüzünün en parlak yıldızı", "Güneş'e en yakın yıldız"], a: "Bu küçük kırmızı cücenin çevresinde yaklaşık Dünya büyüklüğünde yedi gezegen dolanır. Birkaçı yaşanabilir bölgededir." },
  { id: "p02-172", k: "Uzay", s: "Proxima Centauri b neden ilgi çeker?", d: "En yakın yıldızın yaşanabilir bölgesinde", y: ["Yüzeyinde su kanıtlandı", "Güneş Sistemi'ne doğru geliyor"], a: "Bize en yakın ötegezegendir. Ancak yıldızının güçlü parlamaları yüzünden yaşama elverişli olup olmadığı bilinmiyor." },
  { id: "p02-173", k: "Uzay", s: "Hiçbir yıldıza bağlı olmadan uzayda dolaşan gezegenlere ne denir?", d: "Haydut gezegen", y: ["Cüce gezegen", "Kuyruklu gezegen"], a: "Bu gezegenler oluştukları sistemden fırlatılmış olabilir. Işık yansıtacak bir yıldızları olmadığı için bulunmaları çok zordur." },
  { id: "p02-174", k: "Uzay", s: "Bugünkü uzay araçlarının hızıyla en yakın yıldıza gitmek yaklaşık ne kadar sürerdi?", d: "On binlerce yıl", y: ["Birkaç ay", "Birkaç on yıl"], a: "Voyager 1 gibi hızlı bir araç bile 4,2 ışık yılı uzaklıktaki Proxima Centauri'ye ancak on binlerce yılda ulaşabilirdi." },
  { id: "p02-175", k: "Uzay", s: "Gezegen geçişi sırasında ötegezegenin atmosferi nasıl incelenir?", d: "Atmosferden süzülen yıldız ışığıyla", y: ["Atmosfere sonda indirerek", "Radar dalgalarıyla"], a: "Yıldız ışığının bir kısmı gezegenin atmosferinden geçer. Atmosferdeki gazlar belirli renkleri soğurarak tayfta iz bırakır." },
  { id: "p02-176", k: "Uzay", s: "Genç yıldızların çevresinde gezegenlerin oluştuğu gaz ve toz diskine ne denir?", d: "Öngezegen diski", y: ["Gezegenimsi bulutsu", "Galaktik disk"], a: "Diskteki toz taneleri yapışıp büyüyerek zamanla gezegenleri oluşturur. Teleskoplar bu disklerde gezegenlerin açtığı boşlukları görüntüledi." },
  { id: "p02-177", k: "Uzay", s: "Gece gökyüzünün neden karanlık olduğu sorusuna ne ad verilir?", d: "Olbers paradoksu", y: ["Fermi paradoksu", "İkizler paradoksu"], a: "Evren sonsuz ve sonsuz yaşlı olsaydı her yönde bir yıldız görür, gökyüzü aydınlık olurdu. Evrenin sonlu yaşı bu sorunun yanıtının parçasıdır." },
  { id: "p02-178", k: "Uzay", s: "\"Akıllı yaşam yaygınsa neden hiç iz bulamadık?\" sorusuna ne ad verilir?", d: "Fermi paradoksu", y: ["Olbers paradoksu", "Drake paradoksu"], a: "Fizikçi Enrico Fermi'nin 1950'de sorduğu \"Herkes nerede?\" sorusuna dayanır." },
  { id: "p02-179", k: "Uzay", s: "Drake denklemi neyi tahmin etmek için geliştirildi?", d: "Galaksideki iletişim kurabilen uygarlık sayısını", y: ["Bir yıldızın ömrünü", "Evrenin genişleme hızını"], a: "Frank Drake 1961'de bu denklemi yazdı. Denklemdeki çoğu çarpan bilinmediği için sonuç tahminden tahmine büyük fark gösterir." },
  { id: "p02-180", k: "Uzay", s: "SETI kısaltması hangi çalışma alanını anlatır?", d: "Dünya dışı akıllı yaşam arayışı", y: ["Uzay çöpü takibi", "Güneş fırtınası tahmini"], a: "SETI araştırmacıları radyo teleskoplarıyla yapay görünen sinyaller arar. Şimdiye kadar doğrulanmış bir sinyal bulunmadı." },
  { id: "p02-181", k: "Uzay", s: "1977'de alınan, kaynağı hâlâ açıklanamamış ünlü radyo sinyaline ne denir?", d: "Wow! sinyali", y: ["LGM sinyali", "Arecibo sinyali"], a: "Sinyali gören gökbilimci çıktının kenarına \"Wow!\" yazdı. Aynı yön defalarca dinlendi, ama sinyal bir daha yakalanmadı." },
  { id: "p02-182", k: "Uzay", s: "1974'te Arecibo radyo teleskobundan gönderilen mesaj hangi hedefe yöneltildi?", d: "M13 küresel yıldız kümesi", y: ["Andromeda Galaksisi", "Proxima Centauri"], a: "Mesaj, sayıları, DNA'yı ve insan figürünü anlatan basit bir resim içeriyordu. Hedefe ulaşması on binlerce yıl sürecek." },
  { id: "p02-183", k: "Uzay", s: "Işık hızına yakın yolculuk yapıp dönen bir ikiz, Dünya'da kalan kardeşine göre nasıl olur?", d: "Daha genç", y: ["Daha yaşlı", "Aynı yaşta"], a: "Özel göreliliğe göre çok hızlı hareket edenin zamanı daha yavaş akar. Buna ikizler paradoksu denir, ama gerçekte bir çelişki yoktur." },
  { id: "p02-184", k: "Uzay", s: "Görelilik kuramına göre kütlesi olan bir cisim ışık hızına ulaşabilir mi?", d: "Hayır", y: ["Evet, yeterli yakıtla", "Evet, yalnız boşlukta"], a: "Cisim ışık hızına yaklaştıkça onu daha da hızlandırmak için gereken enerji sonsuza gider." },
  { id: "p02-185", k: "Uzay", s: "Toz bulutlarının içindeki yeni doğan yıldızları görmek için hangi ışık kullanılır?", d: "Kızılötesi", y: ["Morötesi", "Görünür ışık"], a: "Kızılötesi ışık tozun içinden görünür ışığa göre çok daha kolay geçer. James Webb'in kızılötesinde çalışmasının nedenlerinden biri budur." },
  { id: "p02-186", k: "Uzay", s: "Uzaydan gelen radyo dalgalarını 1930'larda ilk fark eden mühendis kimdir?", d: "Karl Jansky", y: ["Guglielmo Marconi", "Nikola Tesla"], a: "Jansky, telefon hatlarındaki paraziti araştırırken Samanyolu'nun merkezinden gelen radyo yayınını buldu. Radyo gökbilimi böyle doğdu." },
  { id: "p02-187", k: "Uzay", s: "Radyo gökbilimciler galaksideki nötr hidrojen gazını hangi dalga boyunda izler?", d: "21 santimetre", y: ["21 metre", "21 milimetre"], a: "Hidrojen atomlarının yaydığı bu ışıma sayesinde Samanyolu'nun sarmal kolları haritalandı." },
  { id: "p02-188", k: "Uzay", s: "X-ışını teleskopları neden uzaya gönderilir?", d: "Atmosfer X-ışınlarını soğurur", y: ["Uzayda hava daha sıcaktır", "X-ışınları yalnız gece gelir"], a: "Atmosferimiz bizi uzaydan gelen X-ışınlarından korur. Bu yüzden bu ışığı görmek için atmosferin üstüne çıkmak gerekir." },
  { id: "p02-189", k: "Uzay", s: "NASA'nın 1999'da fırlatılan X-ışını gözlemevinin adı nedir?", d: "Chandra", y: ["Spitzer", "Kepler"], a: "Adını, beyaz cücelerin kütle sınırını hesaplayan Subrahmanyan Chandrasekhar'dan alır. Kara delikleri ve sıcak gazları inceler." },
  { id: "p02-190", k: "Uzay", s: "NASA'nın Büyük Gözlemevleri arasındaki kızılötesi uzay teleskobu hangisidir?", d: "Spitzer", y: ["Chandra", "Compton"], a: "Spitzer 2003-2020 arasında çalıştı. Toz bulutlarındaki yıldızları ve ötegezegenleri kızılötesinde inceledi." },
  { id: "p02-191", k: "Uzay", s: "NASA'nın \"Büyük Gözlemevleri\" programında kaç uzay teleskobu vardı?", d: "Dört", y: ["İki", "Altı"], a: "Hubble, Compton, Chandra ve Spitzer, her biri farklı türde ışığı gözlemek için tasarlandı." },
  { id: "p02-192", k: "Uzay", s: "Kozmik mikrodalga arka planı ayrıntılı haritalayan ESA uydusu hangisidir?", d: "Planck", y: ["Gaia", "Rosetta"], a: "Planck 2009-2013 arasında çalıştı. Ölçümleri evrenin yaşını ve içeriğini büyük bir kesinlikle belirledi." },
  { id: "p02-193", k: "Uzay", s: "ESA'nın Gaia uydusu ne yapmak için tasarlandı?", d: "Samanyolu'nun 3 boyutlu haritasını çıkarmak", y: ["Mars'a iniş yapmak", "Güneş rüzgârını toplamak"], a: "Gaia, bir milyardan fazla yıldızın konumunu, uzaklığını ve hareketini olağanüstü bir hassasiyetle ölçtü." },
  { id: "p02-194", k: "Uzay", s: "Carl Sagan'ın evrenin tarihini tek bir yıla sığdırdığı benzetmenin adı nedir?", d: "Kozmik Takvim", y: ["Galaktik Saat", "Yıldız Günlüğü"], a: "Bu takvimde Büyük Patlama 1 Ocak'ta olur. İnsanlığın yazılı tarihi ise 31 Aralık'ın son saniyelerine sığar." },
  { id: "p02-195", k: "Uzay", s: "Büyük Patlama'nın hemen ardından evrenin aşırı hızlı genişlediğini öne süren fikir hangisidir?", d: "Kozmik enflasyon", y: ["Sabit durum modeli", "Kıta kayması"], a: "Alan Guth 1980'de bu fikri ortaya attı. Enflasyon, evrenin neden her yönde bu kadar düzgün göründüğünü açıklamaya yardım eder." },
  { id: "p02-196", k: "Uzay", s: "Evrenin başlangıcı olmadığını savunan, Büyük Patlama'ya rakip model hangisiydi?", d: "Sabit durum modeli", y: ["Kozmik enflasyon", "Genel görelilik"], a: "Bu model 1960'larda kozmik mikrodalga arka plan keşfedilince büyük ölçüde terk edildi." },
  { id: "p02-197", k: "Uzay", s: "Gökbilimciler bir yıldızın bize yaklaşıp uzaklaştığını hangi etkiyle ölçer?", d: "Doppler etkisi", y: ["Sera etkisi", "Kelebek etkisi"], a: "Ambulans sireninin yaklaşırken tizleşmesi gibi, yaklaşan yıldızın ışığı maviye, uzaklaşanınki kırmızıya kayar." },
  { id: "p02-198", k: "Uzay", s: "Yıldızlar arası uzaklıklar için \"ışık yılı\" yerine profesyonellerin sık kullandığı birim hangisidir?", d: "Parsek", y: ["Mil", "Deniz mili"], a: "Parsek, paralaks yöntemiyle doğrudan bağlantılı olduğu için gökbilimcilerin işini kolaylaştırır. Kiloparsek ve megaparsek de yaygındır." },
  { id: "p02-199", k: "Uzay", s: "Büyük bir yıldızın süpernova patlamasından sonra geride ne kalabilir?", d: "Nötron yıldızı ya da kara delik", y: ["Beyaz cüce ya da gezegen", "Yalnız boşluk"], a: "Kalıntının türü çöken çekirdeğin kütlesine bağlıdır. Çok ağır çekirdekler kara deliğe, daha hafifleri nötron yıldızına dönüşür." },
  { id: "p02-200", k: "Uzay", s: "Güneş benzeri bir yıldızın kalıntısı olan beyaz cüce çoğunlukla neyden oluşur?", d: "Karbon ve oksijen", y: ["Hidrojen ve helyum", "Demir ve nikel"], a: "Yıldız helyumu karbon ve oksijene dönüştürdükten sonra füzyonu sürdüremez. Geriye bu elementlerden oluşan sıcak bir çekirdek kalır." },
  { id: "p02-201", k: "Uzay", s: "İlk yapay uydu Sputnik 1 hangi yıl fırlatıldı?", d: "1957", y: ["1961", "1969"], a: "Sputnik 1, 4 Ekim 1957'de fırlatıldı. Bu olay ABD ile Sovyetler Birliği arasındaki uzay yarışını başlattı." },
  { id: "p02-202", k: "Uzay", s: "Sputnik 1'i hangi ülke fırlattı?", d: "Sovyetler Birliği", y: ["ABD", "Çin"], a: "Yaklaşık 58 cm çapındaki bu metal küre, yaklaşık üç ay Dünya'nın çevresinde dolandıktan sonra atmosfere girip yandı." },
  { id: "p02-203", k: "Uzay", s: "Sputnik 1 Dünya'ya ne gönderiyordu?", d: "Basit \"bip\" radyo sinyalleri", y: ["Bulut fotoğrafları", "Canlı televizyon görüntüsü"], a: "Sinyaller amatör radyocular tarafından da dinlenebiliyordu. Uydunun pilleri yaklaşık üç hafta dayandı." },
  { id: "p02-204", k: "Uzay", s: "Dünya yörüngesine çıkan ilk hayvan hangisidir?", d: "Köpek Laika", y: ["Şempanze Ham", "Kedi Félicette"], a: "Laika 1957'de Sputnik 2 ile yörüngeye çıktı. O dönemde geri dönüş teknolojisi olmadığından görevden sağ dönmesi mümkün değildi." },
  { id: "p02-205", k: "Uzay", s: "1947'de bir V-2 roketiyle uzaya gönderilen ilk canlılar hangileriydi?", d: "Meyve sinekleri", y: ["Köpekler", "Maymunlar"], a: "ABD'nin fırlattığı roketteki meyve sinekleri, radyasyonun canlılara etkisini anlamak için gönderildi ve kapsülle sağ geri döndü." },
  { id: "p02-206", k: "Uzay", s: "1960'ta yörüngeye çıkıp sağ dönen Sovyet köpekleri kimlerdi?", d: "Belka ve Strelka", y: ["Laika ve Ham", "Félix ve Albert"], a: "Belka ve Strelka bir gün yörüngede kaldıktan sonra sağ salim döndü. Strelka'nın yavrularından biri ABD Başkanı Kennedy'ye hediye edildi." },
  { id: "p02-207", k: "Uzay", s: "Uzaya çıkan ilk insan kimdir?", d: "Yuri Gagarin", y: ["Neil Armstrong", "Alan Shepard"], a: "Sovyet pilot Yuri Gagarin, Vostok 1 kapsülüyle Dünya'nın çevresinde bir tur attı." },
  { id: "p02-208", k: "Uzay", s: "Yuri Gagarin uzaya hangi tarihte çıktı?", d: "12 Nisan 1961", y: ["20 Temmuz 1969", "4 Ekim 1957"], a: "Bu tarih bugün Birleşmiş Milletler tarafından Uluslararası İnsanlı Uzay Uçuşu Günü olarak anılır." },
  { id: "p02-209", k: "Uzay", s: "Gagarin'in uzaya çıktığı kapsülün adı nedir?", d: "Vostok 1", y: ["Soyuz 1", "Apollo 1"], a: "Vostok, Rusçada \"doğu\" demektir. Kapsül tek kişilikti ve uçuş tamamen otomatik kontrol ediliyordu." },
  { id: "p02-210", k: "Uzay", s: "Gagarin'in tarihî uçuşu yaklaşık ne kadar sürdü?", d: "108 dakika", y: ["3 gün", "10 dakika"], a: "Gagarin yaklaşık bir buçuk saatte Dünya'nın çevresini bir kez dolandı. İnişte kapsülden fırlatılıp paraşütle yere indi." },
  { id: "p02-211", k: "Uzay", s: "Gagarin fırlatma anında hangi ünlü sözü söyledi?", d: "\"Haydi gidelim!\"", y: ["\"Houston, bir sorunumuz var\"", "\"Kartal indi\""], a: "Rusça \"Poyekhali!\" sözü bir anda simgeleşti. Diğer iki söz Apollo görevlerinden kalmadır." },
  { id: "p02-212", k: "Uzay", s: "Uzaya giden ilk Amerikalı kimdir?", d: "Alan Shepard", y: ["John Glenn", "Neil Armstrong"], a: "Shepard Mayıs 1961'de Freedom 7 kapsülüyle yaklaşık 15 dakikalık yörünge altı bir uçuş yaptı." },
  { id: "p02-213", k: "Uzay", s: "Dünya yörüngesinde dolanan ilk Amerikalı kimdir?", d: "John Glenn", y: ["Alan Shepard", "Buzz Aldrin"], a: "Glenn 1962'de Friendship 7 ile Dünya'nın çevresini üç kez dolandı. 1998'de 77 yaşında uzay mekiğiyle yeniden uzaya çıktı." },
  { id: "p02-214", k: "Uzay", s: "Uzaya giden ilk kadın kimdir?", d: "Valentina Tereşkova", y: ["Sally Ride", "Svetlana Savitskaya"], a: "Tereşkova 1963'te Vostok 6 ile tek başına uçtu ve üç günde Dünya'nın çevresini 48 kez dolandı." },
  { id: "p02-215", k: "Uzay", s: "Uzaya giden ilk Amerikalı kadın kimdir?", d: "Sally Ride", y: ["Valentina Tereşkova", "Mae Jemison"], a: "Sally Ride 1983'te Challenger uzay mekiğiyle uçtu. Fizikçiydi ve sonradan bilim eğitimi için çalıştı." },
  { id: "p02-216", k: "Uzay", s: "Uzay yürüyüşü yapan ilk insan kimdir?", d: "Aleksey Leonov", y: ["Yuri Gagarin", "Ed White"], a: "Leonov 1965'te Voskhod 2'den çıkıp yaklaşık 12 dakika uzayda kaldı. Şişen giysisi yüzünden kapsüle geri girmekte zorlandı." },
  { id: "p02-217", k: "Uzay", s: "Uzay yürüyüşü yapan ilk Amerikalı kimdir?", d: "Ed White", y: ["John Glenn", "Michael Collins"], a: "Ed White 1965'te Gemini 4 göreviyle uzay yürüyüşü yaptı. Elindeki küçük bir gaz tabancasıyla hareket etmeyi denedi." },
  { id: "p02-218", k: "Uzay", s: "Uzay yürüyüşü yapan ilk kadın kimdir?", d: "Svetlana Savitskaya", y: ["Valentina Tereşkova", "Sally Ride"], a: "Sovyet kozmonot Savitskaya 1984'te Salyut 7 istasyonunun dışında çalıştı. Uzaya iki kez giden ilk kadın da odur." },
  { id: "p02-219", k: "Uzay", s: "ABD'nin insanlı uzay programları hangi sırayla ilerledi?", d: "Mercury, Gemini, Apollo", y: ["Apollo, Gemini, Mercury", "Gemini, Mercury, Apollo"], a: "Mercury tek, Gemini iki, Apollo üç kişilikti. Her program bir sonrakinin gerektirdiği becerileri denedi." },
  { id: "p02-220", k: "Uzay", s: "Gemini programının en önemli hedeflerinden biri neydi?", d: "Uzayda buluşma ve kenetlenmeyi denemek", y: ["Ay'a insan indirmek", "Mars'a sonda göndermek"], a: "Gemini 8, 1966'da başka bir araçla kenetlenen ilk uzay aracı oldu. Komutanı Neil Armstrong'du." },
  { id: "p02-221", k: "Uzay", s: "Apollo 11'in Ay'a iniş tarihi nedir?", d: "20 Temmuz 1969", y: ["12 Nisan 1961", "14 Aralık 1972"], a: "Ay modülü Eagle, Sükûnet Denizi'ne indi. İniş dünya çapında yüz milyonlarca kişi tarafından izlendi." },
  { id: "p02-222", k: "Uzay", s: "Ay'a ayak basan ikinci insan kimdir?", d: "Buzz Aldrin", y: ["Michael Collins", "Pete Conrad"], a: "Aldrin, Armstrong'dan yaklaşık 20 dakika sonra Ay yüzeyine çıktı. İkili Ay'da yaklaşık iki buçuk saat yürüdü." },
  { id: "p02-224", k: "Uzay", s: "Apollo 11'in Ay modülünün adı nedir?", d: "Eagle (Kartal)", y: ["Columbia", "Odyssey"], a: "Armstrong inişten sonra \"Kartal indi\" diye bildirdi. Columbia ise komuta modülünün adıydı." },
  { id: "p02-227", k: "Uzay", s: "Ay'da yürüyen son insan kimdir?", d: "Eugene Cernan", y: ["Neil Armstrong", "Buzz Aldrin"], a: "Apollo 17 komutanı Cernan, Ay modülüne en son binen kişiydi. Kızının baş harflerini Ay tozuna yazdığını anlatmıştır." },
  { id: "p02-228", k: "Uzay", s: "Apollo 13 görevinde ne oldu?", d: "Oksijen tankı patladı, ekip sağ döndü", y: ["Ay'a başarıyla inildi", "Fırlatmada roket patladı"], a: "Patlama yüzünden Ay'a iniş iptal edildi. Ekip Ay modülünü cankurtaran gibi kullanıp Ay'ın çevresinden dolanarak Dünya'ya döndü." },
  { id: "p02-230", k: "Uzay", s: "Ünlü \"Dünya'nın Doğuşu\" (Earthrise) fotoğrafı hangi görevde çekildi?", d: "Apollo 8", y: ["Apollo 17", "Gemini 4"], a: "William Anders'ın çektiği fotoğraf, Ay ufkunun üzerinde yükselen Dünya'yı gösterir. Çevre hareketinin simgelerinden biri oldu." },
  { id: "p02-231", k: "Uzay", s: "Dünya'nın tam aydınlık yüzünü gösteren \"Mavi Bilye\" fotoğrafı hangi görevde çekildi?", d: "Apollo 17", y: ["Apollo 8", "Apollo 13"], a: "Fotoğraf 1972'de Ay'a giderken çekildi. Tarihte en çok çoğaltılan fotoğraflardan biri sayılır." },
  { id: "p02-232", k: "Uzay", s: "Apollo 1 felaketinde ne oldu?", d: "Yer testinde kapsülde yangın çıktı", y: ["Roket fırlatmada patladı", "Kapsül okyanusta battı"], a: "1967'deki yangında üç astronot hayatını kaybetti. Kapsül tasarımı baştan aşağı değiştirildi." },
  { id: "p02-233", k: "Uzay", s: "Apollo astronotlarını Ay'a taşıyan dev roketin adı nedir?", d: "Saturn V", y: ["Atlas", "Soyuz"], a: "Yaklaşık 110 metre boyundaki Saturn V, bugün bile uçurulmuş en güçlü roketler arasında sayılır." },
  { id: "p02-234", k: "Uzay", s: "Ay'da ilk kez elektrikli bir araçla dolaşılan görev hangisidir?", d: "Apollo 15", y: ["Apollo 11", "Apollo 13"], a: "Ay Gezi Aracı (LRV) sayesinde astronotlar kilometrelerce uzağa gidip daha çok örnek topladı. Araç son üç Apollo görevinde kullanıldı." },
  { id: "p02-235", k: "Uzay", s: "Apollo görevleri Dünya'ya toplam yaklaşık ne kadar Ay örneği getirdi?", d: "380 kilogram", y: ["3,8 kilogram", "38 ton"], a: "Bu örnekler bugün hâlâ inceleniyor. Ay'ın yaşını ve kökenini anlamada temel kaynak oldular." },
  { id: "p02-236", k: "Uzay", s: "ABD Başkanı Kennedy, 1961'de Ay'a insan indirmek için hangi hedefi koydu?", d: "On yıl bitmeden", y: ["Yüzyıl bitmeden", "Beş yıl içinde"], a: "Kennedy 1961'de Kongre'de bu hedefi açıkladı. 1962'deki \"Ay'a gitmeyi seçiyoruz\" konuşması da ünlüdür. Hedefe 1969'da ulaşıldı." },
  { id: "p02-239", k: "Uzay", s: "Başka bir gök cisminde dolaşan ilk uzaktan kumandalı gezgin hangisidir?", d: "Lunokhod 1", y: ["Sojourner", "Curiosity"], a: "Sovyet gezgini Lunokhod 1, 1970'te Ay'a indi ve aylarca yeryüzünden kumandayla yönetildi." },
  { id: "p02-240", k: "Uzay", s: "Başka bir gezegene yumuşak iniş yapıp veri gönderen ilk araç hangisidir?", d: "Venera 7", y: ["Viking 1", "Mariner 4"], a: "Sovyet sondası Venera 7, 1970'te Venüs'e indi. Yüzeydeki aşırı sıcak ve basınca rağmen kısa süre veri gönderebildi." },
  { id: "p02-244", k: "Uzay", s: "İkiz Voyager uzay araçları hangi yıl fırlatıldı?", d: "1977", y: ["1967", "1987"], a: "Gezegenlerin ender görülen dizilişinden yararlanan Voyager'lar, dış gezegenleri ziyaret edip Güneş Sistemi'nin dışına yöneldi." },
  { id: "p02-245", k: "Uzay", s: "Yıldızlararası uzaya ulaşan ilk insan yapımı araç hangisidir?", d: "Voyager 1", y: ["Pioneer 10", "New Horizons"], a: "Voyager 1, 2012'de Güneş rüzgârının etkisinin bittiği sınırı geçti. Voyager 2 de 2018'de onu izledi." },
  { id: "p02-246", k: "Uzay", s: "Uranüs ve Neptün'ü yakından ziyaret eden tek uzay aracı hangisidir?", d: "Voyager 2", y: ["Voyager 1", "Cassini"], a: "Voyager 2, Uranüs'ün yanından 1986'da, Neptün'ün yanından 1989'da geçti. Bu iki gezegenin yakın fotoğraflarının çoğu ondan gelir." },
  { id: "p02-247", k: "Uzay", s: "Voyager araçlarına olası uzaylılar için konan nesne nedir?", d: "Altın Plak", y: ["Gümüş Bayrak", "Elmas Disk"], a: "Plakta Dünya'dan sesler, müzikler, 55 dilde selamlar ve görüntüler var. Çalma talimatları da üzerine kazınmış." },
  { id: "p02-248", k: "Uzay", s: "Dünya'yı küçücük bir ışık noktası olarak gösteren \"Soluk Mavi Nokta\" fotoğrafını hangi araç çekti?", d: "Voyager 1", y: ["Hubble", "Apollo 17"], a: "Fotoğraf 1990'da yaklaşık 6 milyar km uzaklıktan, Carl Sagan'ın önerisiyle çekildi." },
  { id: "p02-249", k: "Uzay", s: "Pioneer 10 ve 11'e konan plakalarda Dünya'nın yeri neye göre gösterildi?", d: "Pulsarlara göre", y: ["Kuzey Yıldızı'na göre", "Ay'ın evrelerine göre"], a: "Plaka, Güneş'in konumunu 14 pulsarın yönü ve atım hızlarıyla belirten bir harita içerir. Aynı harita Voyager plaklarında da var." },
  { id: "p02-250", k: "Uzay", s: "Huygens sondası 2005'te hangi gök cismine indi?", d: "Titan", y: ["Europa", "Ganymede"], a: "ESA'nın Huygens sondası, Satürn'ün uydusu Titan'a indi. Dış Güneş Sistemi'nde bir cisme inen ilk araçtır." },
  { id: "p02-251", k: "Uzay", s: "Bir kuyruklu yıldıza iniş yapan ilk araç hangisidir?", d: "Philae", y: ["Huygens", "Hayabusa"], a: "ESA'nın Rosetta görevindeki Philae, 2014'te 67P kuyruklu yıldızına indi. İnişte sekip bir gölgeliğe düştü." },
  { id: "p02-252", k: "Uzay", s: "Bir asteroitten Dünya'ya örnek getiren ilk görev hangisidir?", d: "Japonya'nın Hayabusa'sı", y: ["NASA'nın Kepler'i", "ESA'nın Rosetta'sı"], a: "Hayabusa, Itokawa asteroitinden topladığı küçük tanelerle 2010'da Dünya'ya döndü. Görev birçok arızaya rağmen başarıya ulaştı." },
  { id: "p02-253", k: "Uzay", s: "NASA hangi yıl kuruldu?", d: "1958", y: ["1945", "1969"], a: "NASA, Sputnik'in yarattığı şokun ardından 1958'de kuruldu. Ondan önce ABD'nin uzay çalışmaları farklı kurumlara dağılmıştı." },
  { id: "p02-254", k: "Uzay", s: "Avrupa Uzay Ajansı'nın kısaltması nedir?", d: "ESA", y: ["NASA", "JAXA"], a: "ESA 1975'te kuruldu ve merkezi Paris'tedir. Fırlatmalarının çoğu Fransız Guyanası'ndaki Kourou üssünden yapılır." },
  { id: "p02-255", k: "Uzay", s: "JAXA hangi ülkenin uzay ajansıdır?", d: "Japonya", y: ["Çin", "Güney Kore"], a: "JAXA 2003'te Japonya'nın üç uzay kurumunun birleşmesiyle kuruldu. Hayabusa görevleri en bilinen çalışmalarıdır." },
  { id: "p02-256", k: "Uzay", s: "ISRO hangi ülkenin uzay ajansıdır?", d: "Hindistan", y: ["İsrail", "İran"], a: "ISRO 1969'da kuruldu. Düşük bütçeli ama başarılı görevleriyle tanınır." },
  { id: "p02-257", k: "Uzay", s: "Türkiye Uzay Ajansı hangi yıl kuruldu?", d: "2018", y: ["1998", "2008"], a: "Türkiye Uzay Ajansı (TUA), Aralık 2018'de kuruldu ve merkezi Ankara'dadır." },
  { id: "p02-258", k: "Uzay", s: "Uzaya giden ilk Türk astronot kimdir?", d: "Alper Gezeravcı", y: ["Tuva Cihangir Atasever", "Arif Karabeyoğlu"], a: "Alper Gezeravcı Ocak 2024'te Uluslararası Uzay İstasyonu'na gitti ve orada yaklaşık iki hafta deney yaptı." },
  { id: "p02-259", k: "Uzay", s: "Alper Gezeravcı uzayda hangi istasyonda kaldı?", d: "Uluslararası Uzay İstasyonu", y: ["Tiangong", "Mir"], a: "Gezeravcı, Axiom Space'in Ax-3 göreviyle SpaceX'in Dragon kapsülünde istasyona ulaştı." },
  { id: "p02-260", k: "Uzay", s: "Uzaya giden ikinci Türk kimdir?", d: "Tuva Cihangir Atasever", y: ["Alper Gezeravcı", "Mehmet Öz"], a: "Atasever Haziran 2024'te Virgin Galactic'in uzay uçağıyla yörünge altı bir uçuş yaptı ve uzayda deneyler gerçekleştirdi." },
  { id: "p02-261", k: "Uzay", s: "Türkiye'nin yörüngede başarıyla çalışan ilk haberleşme uydusu hangisidir?", d: "Türksat 1B", y: ["Göktürk-1", "Türksat 6A"], a: "1994'te fırlatılan Türksat 1B, Türkiye'nin uydu haberleşme çağını başlattı. Ondan önceki Türksat 1A fırlatmada kaybolmuştu." },
  { id: "p02-262", k: "Uzay", s: "Türkiye'nin yerli olarak geliştirdiği ilk haberleşme uydusu hangisidir?", d: "Türksat 6A", y: ["Türksat 1B", "Türksat 3A"], a: "Türksat 6A Temmuz 2024'te fırlatıldı. Tasarım ve üretimi büyük ölçüde Türkiye'de yapıldı." },
  { id: "p02-263", k: "Uzay", s: "Uzaya giden ilk Çinli astronot kimdir?", d: "Yang Liwei", y: ["Liu Yang", "Zhai Zhigang"], a: "Yang Liwei 2003'te Shenzhou 5 ile uçtu. Böylece Çin, kendi imkânlarıyla insan gönderen üçüncü ülke oldu." },
  { id: "p02-264", k: "Uzay", s: "Çin'in uzay istasyonunun adı nedir?", d: "Tiangong", y: ["Mir", "Skylab"], a: "Tiangong \"Gök Sarayı\" anlamına gelir. Ana modülü 2021'de fırlatıldı." },
  { id: "p02-265", k: "Uzay", s: "Ay'ın uzak yüzüne iniş yapan ilk araç hangisidir?", d: "Çin'in Chang'e 4'ü", y: ["ABD'nin Apollo 17'si", "Sovyetlerin Luna 9'u"], a: "Chang'e 4, 2019'da Ay'ın uzak yüzüne indi. Dünya ile iletişim için Ay'ın arkasını gören bir aktarma uydusu kullanıldı." },
  { id: "p02-266", k: "Uzay", s: "Hindistan'ın 2023'te Ay'ın güney kutbu yakınına inen görevi hangisidir?", d: "Chandrayaan-3", y: ["Mangalyaan", "Gaganyaan"], a: "Chandrayaan-3 ile Hindistan, Ay'ın güney kutbu bölgesine yumuşak iniş yapan ilk ülke oldu." },
  { id: "p02-267", k: "Uzay", s: "Tarihteki ilk uzay istasyonu hangisidir?", d: "Salyut 1", y: ["Skylab", "Mir"], a: "Sovyetler Birliği Salyut 1'i 1971'de fırlattı. İstasyona ilk kez yerleşen ekip, dönüşte kapsüldeki bir arıza yüzünden hayatını kaybetti." },
  { id: "p02-268", k: "Uzay", s: "ABD'nin ilk uzay istasyonu hangisidir?", d: "Skylab", y: ["Mir", "Freedom"], a: "Skylab 1973'te fırlatıldı ve üç ekibe ev sahipliği yaptı. 1979'da atmosfere girdi, parçaları Avustralya'ya düştü." },
  { id: "p02-269", k: "Uzay", s: "1986-2001 arasında yörüngede kalan Sovyet-Rus uzay istasyonu hangisidir?", d: "Mir", y: ["Salyut 1", "Tiangong"], a: "Mir, modül modül birleştirilen ilk büyük istasyondu. Görev süresinin sonunda kontrollü olarak Pasifik Okyanusu'na indirildi." },
  { id: "p02-270", k: "Uzay", s: "1975'te ABD ve Sovyet uzay araçlarının yörüngede kenetlendiği görevin adı nedir?", d: "Apollo-Soyuz", y: ["Gemini-Vostok", "Mercury-Salyut"], a: "İki ülkenin astronotları yörüngede el sıkıştı. Bu görev uzay yarışının sonunu ve iş birliğinin başlangıcını simgeler." },
  { id: "p02-271", k: "Uzay", s: "Uzay mekiği ilk kez hangi yıl uçtu?", d: "1981", y: ["1969", "1991"], a: "İlk uçuşu Columbia mekiği yaptı. Mekik, yeniden kullanılabilen ilk insanlı uzay aracı sistemiydi." },
  { id: "p02-272", k: "Uzay", s: "Uzay mekiği programının son uçuşunu hangi mekik yaptı?", d: "Atlantis", y: ["Columbia", "Challenger"], a: "Atlantis Temmuz 2011'de son kez indi. Program 30 yılda toplam 135 uçuş yaptı." },
  { id: "p02-273", k: "Uzay", s: "1986'daki Challenger kazasına ne yol açtı?", d: "Soğukta sertleşen bir conta", y: ["Bir göktaşı çarpması", "Pilot hatası"], a: "Soğuk havada esnekliğini yitiren O-halka contası sızdırdı ve mekik kalkıştan 73 saniye sonra parçalandı. Yedi astronot hayatını kaybetti." },
  { id: "p02-274", k: "Uzay", s: "2003'teki Columbia mekiği kazasının nedeni neydi?", d: "Kanatta köpük darbesinin açtığı hasar", y: ["Motor patlaması", "Yakıt sızıntısı"], a: "Kalkışta yakıt tankından kopan köpük parçası kanadı deldi. Mekik dönüşte atmosfere girerken parçalandı, yedi astronot öldü." },
  { id: "p02-275", k: "Uzay", s: "Sovyetler Birliği'nin uzay mekiğinin adı nedir?", d: "Buran", y: ["Soyuz", "Vostok"], a: "Buran 1988'de yalnız bir kez, insansız olarak uçtu ve otomatik olarak iniş yaptı. Program daha sonra iptal edildi." },
  { id: "p02-276", k: "Uzay", s: "ABD'nin ilk yapay uydusu hangisidir?", d: "Explorer 1", y: ["Vanguard 1", "Telstar 1"], a: "1958'de fırlatılan Explorer 1, Dünya'yı çevreleyen radyasyon kuşaklarını keşfetti. Bu kuşaklar bugün Van Allen kuşakları diye bilinir." },
  { id: "p02-277", k: "Uzay", s: "1962'de okyanus ötesine canlı televizyon yayını aktaran ilk uydu hangisidir?", d: "Telstar 1", y: ["Sputnik 1", "Explorer 1"], a: "Telstar 1, Avrupa ile Kuzey Amerika arasında televizyon görüntüsü aktardı. Uydu iletişim çağının simgelerinden biri oldu." },
  { id: "p02-278", k: "Uzay", s: "İlk sıvı yakıtlı roketi 1926'da fırlatan mühendis kimdir?", d: "Robert Goddard", y: ["Wernher von Braun", "Sergey Korolev"], a: "Goddard'ın roketi yalnız birkaç saniye uçup 12 metre kadar yükseldi. Yine de modern roketçiliğin başlangıcı sayılır." },
  { id: "p02-279", k: "Uzay", s: "Roket denklemini geliştiren ve uzay yolculuğunun kuramsal öncüsü sayılan Rus bilim insanı kimdir?", d: "Konstantin Tsiolkovsky", y: ["Yuri Gagarin", "Dmitri Mendeleyev"], a: "Tsiolkovsky 1900'lerin başında çok kademeli roketler ve uzay istasyonları gibi fikirleri ortaya attı." },
  { id: "p02-280", k: "Uzay", s: "Sovyet uzay programının baş tasarımcısı kimdi?", d: "Sergey Korolev", y: ["Konstantin Tsiolkovsky", "Aleksey Leonov"], a: "Sputnik ve Gagarin'in uçuşunun arkasında Korolev vardı. Kimliği ölümüne kadar gizli tutuldu." },
  { id: "p02-281", k: "Uzay", s: "Saturn V roketinin geliştirilmesine liderlik eden mühendis kimdir?", d: "Wernher von Braun", y: ["Robert Goddard", "Sergey Korolev"], a: "Von Braun, savaştan sonra ABD'ye götürülen Alman roket mühendislerindendi. Ekibi Apollo'nun dev roketini geliştirdi." },
  { id: "p02-282", k: "Uzay", s: "Uzaya ulaşan ilk insan yapımı cisim hangisidir?", d: "Bir V-2 roketi", y: ["Sputnik 1", "Vostok 1"], a: "Almanların V-2 roketi 1944'te bir test uçuşunda 100 km sınırını aştı. Savaştan sonra V-2'ler bilimsel araştırmalarda da kullanıldı." },
  { id: "p02-283", k: "Uzay", s: "İlk paralı uzay turisti kimdir?", d: "Dennis Tito", y: ["Richard Branson", "Elon Musk"], a: "Amerikalı iş insanı Dennis Tito 2001'de bir Soyuz aracıyla Uluslararası Uzay İstasyonu'na gitti." },
  { id: "p02-284", k: "Uzay", s: "Uluslararası Uzay İstasyonu'na astronot taşıyan ilk özel şirket aracı hangisidir?", d: "Crew Dragon", y: ["Soyuz", "Uzay mekiği"], a: "SpaceX'in Crew Dragon kapsülü 2020'deki Demo-2 göreviyle iki NASA astronotunu istasyona taşıdı." },
  { id: "p02-285", k: "Uzay", s: "Yörüngeye yük taşıyıp ilk kademesi dikine iniş yapan ilk roket hangisidir?", d: "Falcon 9", y: ["Saturn V", "Ariane 5"], a: "SpaceX'in Falcon 9 roketinin ilk kademesi Aralık 2015'te fırlatmadan sonra yere indi. Bu, roketlerin yeniden kullanımına kapı açtı." },
  { id: "p02-286", k: "Uzay", s: "1967 tarihli Dış Uzay Antlaşması neyi yasaklar?", d: "Gök cisimleri üzerinde egemenlik iddiasını", y: ["Uzaya insan göndermeyi", "Uydu fırlatmayı"], a: "Antlaşmaya göre hiçbir ülke Ay'ı ya da başka bir gök cismini sahiplenemez. Yörüngeye nükleer silah yerleştirmek de yasaktır." },
  { id: "p02-287", k: "Uzay", s: "Rus uzay yolcularına ne ad verilir?", d: "Kozmonot", y: ["Taykonot", "Astronot"], a: "ABD ve Avrupa'da astronot, Rusya'da kozmonot, Çin'de ise taykonot sözcüğü yaygındır. Hepsi aynı mesleği anlatır." },
  { id: "p02-288", k: "Uzay", s: "Gagarin'in uzaya fırlatıldığı üs hangisidir?", d: "Baykonur", y: ["Cape Canaveral", "Kourou"], a: "Kazakistan'daki Baykonur, dünyanın en eski ve en büyük fırlatma üslerinden biridir. Sputnik 1 de buradan fırlatıldı." },
  { id: "p02-289", k: "Uzay", s: "Apollo görevleri ABD'nin hangi eyaletinden fırlatıldı?", d: "Florida", y: ["Teksas", "Kaliforniya"], a: "Roketler Florida'daki Kennedy Uzay Merkezi'nden kalktı. Görev kontrol ise Teksas'taki Houston'daydı." },
  { id: "p02-290", k: "Uzay", s: "Apollo görevlerinde \"Houston\" denince kastedilen yer neresiydi?", d: "Görev kontrol merkezi", y: ["Fırlatma rampası", "Astronotların okulu"], a: "Houston'daki görev kontrol merkezi, uçuş boyunca astronotlarla sürekli iletişimdeydi. Apollo 13'teki ünlü sözler de buraya söylendi." },
  { id: "p02-291", k: "Uzay", s: "ESA roketleri genellikle nereden fırlatılır?", d: "Fransız Guyanası", y: ["Norveç", "İspanya"], a: "Güney Amerika'daki Kourou üssü ekvatora çok yakındır. Bu konum, Dünya'nın dönüşünden ek hız kazandırır." },
  { id: "p02-292", k: "Uzay", s: "Fırlatma üsleri neden mümkün olduğunca ekvatora yakın kurulur?", d: "Dünya'nın dönüşü rokete hız katar", y: ["Ekvatorda yerçekimi yoktur", "Ekvatorda hava hep açıktır"], a: "Dünya yüzeyi ekvatorda en hızlı döner. Doğuya fırlatılan roket bu hızı bedavaya alır ve yakıttan tasarruf eder." },
  { id: "p02-294", k: "Uzay", s: "Uzay yarışı en çok hangi iki ülke arasında yaşandı?", d: "ABD ve Sovyetler Birliği", y: ["ABD ve Çin", "İngiltere ve Fransa"], a: "Soğuk Savaş döneminde iki süper güç uzaydaki başarıları teknolojik üstünlük göstergesi saydı. Yarış 1957'den 1970'lerin başına kadar sürdü." },
  { id: "p02-295", k: "Uzay", s: "NASA'nın 2022'de Ay'ın çevresine insansız gönderdiği Artemis I görevinde hangi kapsül uçtu?", d: "Orion", y: ["Dragon", "Soyuz"], a: "Orion kapsülü SLS roketiyle fırlatıldı, Ay'ın çevresinde dolanıp Pasifik Okyanusu'na indi." },
  { id: "p02-296", k: "Uzay", s: "Artemis programının adı mitolojide kimden gelir?", d: "Apollo'nun ikiz kız kardeşinden", y: ["Zeus'un babasından", "Bir deniz tanrısından"], a: "Yunan mitolojisinde Artemis, Apollon'un ikizi ve Ay ile ilişkilendirilen tanrıçadır. Ad, Apollo programına bir göndermedir." },
  { id: "p02-297", k: "Uzay", s: "Apollo 11 ile Ay'da bırakılan bir levhada hangi ifade yer alır?", d: "Bütün insanlık için barış içinde geldik", y: ["Bu topraklar ABD'nindir", "Burada ilk kez insan yaşadı"], a: "Levhada \"Bütün insanlık için barış içinde geldik\" anlamına gelen bir yazı ve astronotlarla Başkan Nixon'ın imzaları bulunur." },
  { id: "p02-298", k: "Uzay", s: "Apollo 11 astronotları Dünya'ya döndükten sonra neden karantinaya alındı?", d: "Ay'dan mikrop getirme ihtimaline karşı", y: ["Radyasyon zehirlenmesi yüzünden", "Kemik kırıkları yüzünden"], a: "Ay'da canlı olup olmadığı bilinmediği için astronotlar yaklaşık üç hafta karantinada kaldı. Sonraki görevlerde bu uygulama kaldırıldı." },
  { id: "p02-299", k: "Uzay", s: "Ay'da bir golf topuna vuran Apollo astronotu kimdir?", d: "Alan Shepard", y: ["Neil Armstrong", "John Glenn"], a: "Uzaya giden ilk Amerikalı Shepard, 1971'de Apollo 14'le Ay'a indi ve kalın eldivenleriyle golf topuna vurdu." },
  { id: "p02-300", k: "Uzay", s: "Mercury programı için seçilen ilk ABD astronotu grubuna ne ad verildi?", d: "Mercury Yedilisi", y: ["Apollo Onikilisi", "Gemini Beşlisi"], a: "1959'da seçilen yedi askerî test pilotu, ABD'nin ilk astronotları oldu. Aralarında Alan Shepard ve John Glenn de vardı." },
];
